  ('5834b1ef-78ee-54ac-a8af-4bbb69ee99f6', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Складно, але воно того варте.", "І стеж за вказівками екстрених служб по радіо.", "Попроси сусідку поливати, поки тебе немає."]'::jsonb, 0, null, '{}'::text[], 'Komplicirano je, ali vrijedi.', null, null, 'Прозвучало: «Komplicirano je, ali vrijedi.» — «Складно, але воно того варте.».', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_v5'),
  ('827f62a7-38e1-517c-a35f-9d1275f8806c', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Чи евакуюють кемпінг?", "Ти заблокував картки?", "А як часто їх треба поливати?"]'::jsonb, 2, null, '{}'::text[], 'A koliko često ih trebam zalijevati?', null, null, 'Прозвучало: «A koliko često ih trebam zalijevati?» — «А як часто їх треба поливати?».', (select id from public.lessons where id = '47da19c6-e1f7-589a-87a2-e78e419c206a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('499d6c85-0067-51ee-87d5-c261055fe4a5', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Що радять людям?', 'Narančasto upozorenje za Dalmaciju', '["Їхати на море", "Відчинити вікна", "Уникати перебування надворі"]'::jsonb, 2, null, '{}'::text[], null, 'Za Dalmaciju je izdano narančasto upozorenje zbog olujnog vjetra. Sutra dolazi bura, a na moru će biti valovi do četiri metra. Možda će biti prekid plovidbe i problema na autocesti. Ljudi trebaju izbjegavati boravak vani i skloniti se na sigurno mjesto. Zatvorite prozore i ne ostavljajte stvari na balkonu. Zbog suhog vremena opasnost od šumskih požara je velika, pa vrijedi zabrana loženja vatre. Ako ste u opasnosti, nazovite hitne službe na broj 112.', 'Для Далмації оголошено помаранчеве попередження через штормовий вітер. Завтра прийде бура, а на морі будуть хвилі до чотирьох метрів. Можливі припинення руху суден і проблеми на автомагістралі. Людям слід уникати перебування надворі й сховатися в безпечному місці. Зачиніть вікна й не залишайте речей на балконі. Через суху погоду небезпека лісових пожеж велика, тож діє заборона розпалювати вогонь. Якщо ви в небезпеці, телефонуйте до екстрених служб за номером 112.', 'Текст «Помаранчеве попередження». Правильна відповідь: «Уникати перебування надворі».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('1b82470f-a5c7-58b5-820b-2f499805f64b', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što trebate odvesti?', '["Probat ćemo. Kaput će biti gotov do petka.", "Stari kauč, dva ormara i staru perilicu.", "Pisalo je u kalendaru. Kod nas se imendan rijetko slavi."]'::jsonb, 1, null, '{}'::text[], 'Što trebate odvesti?', null, null, 'Діалог «Старий диван»: «Što trebate odvesti?» (Що вам треба вивезти?) — «Stari kauč, dva ormara i staru perilicu.» (Старий диван, дві шафи й стару пральну машину.).', (select id from public.lessons where id = '5ef67da9-21aa-58fa-91c2-d8144333a756'), 'PUBLISHED', 'claude_assessment_v5'),
  ('667bee53-896f-5591-ab5f-5b4c1f04f730', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Za koje biljke?', '["Jesu, liječnici će Vam ih objasniti.", "Za masline. Želim ih posaditi na terasi.", "Nazvat ću prometno redarstvo i pitati."]'::jsonb, 1, null, '{}'::text[], 'Za koje biljke?', null, null, 'Діалог «У садовому центрі»: «Za koje biljke?» (Для яких рослин?) — «Za masline. Želim ih posaditi na terasi.» (Для оливкових дерев. Хочу посадити їх на терасі.).', (select id from public.lessons where id = '47da19c6-e1f7-589a-87a2-e78e419c206a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4ba73ed3-dc2e-5d1d-aa47-d1f2773bf649', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Možete li ga opisati?', '["Jesu, prije deset godina. Grad se jako promijenio.", "Smeđ je, kožni, s dokumentima i karticama.", "U deset, ako ima mjesta."]'::jsonb, 1, null, '{}'::text[], 'Možete li ga opisati?', null, null, 'Діалог «У бюро знахідок»: «Možete li ga opisati?» (Можете його описати?) — «Smeđ je, kožni, s dokumentima i karticama.» (Він коричневий, шкіряний, з документами й картками.).', (select id from public.lessons where id = '6c0efc81-fd32-55c6-8e57-b1885e387093'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ed8e1ec4-9d2a-5634-a416-6966b7dd6c63', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jesi li blokirao kartice?', '["Так, одразу. На щастя, гроші були в іншій кишені.", "Почекай день-два. Може, хтось поверне його власникові.", "Добре, але завтра таки піду в бюро знахідок."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Jesi li blokirao kartice?
Ivan: Jesam, odmah. Srećom, novac je bio u drugom džepu.
Daša: A osobna iskaznica?
Ivan: I ona je u novčaniku. Moram prijaviti gubitak policiji.
Daša: Pričekaj dan-dva. Možda ga netko vrati vlasniku.
Ivan: Dobro, ali sutra ću ipak otići u ured za izgubljene stvari.', 'Daša: Ти заблокував картки?
Ivan: Так, одразу. На щастя, гроші були в іншій кишені.
Daša: А посвідчення особи?
Ivan: Воно теж у гаманці. Мушу заявити про втрату в поліцію.
Daša: Почекай день-два. Може, хтось поверне його власникові.
Ivan: Добре, але завтра таки піду в бюро знахідок.', 'Діалог «Картки»: «Jesi li blokirao kartice?» — «Jesam, odmah. Srećom, novac je bio u drugom džepu.», тобто «Так, одразу. На щастя, гроші були в іншій кишені.».', (select id from public.lessons where id = '6c0efc81-fd32-55c6-8e57-b1885e387093'), 'PUBLISHED', 'claude_assessment_v5'),
  ('1a6e8be4-d434-5f2c-9c47-ce4603795864', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Hoće li evakuirati kamp?', '["Якщо вітер зміниться, евакуюють. Приготуймо документи про всяк випадок.", "Добре. Наповню й пляшки питною водою.", "Канадери вже тут. Пожежники гасять з ранку."]'::jsonb, 0, null, '{}'::text[], null, 'Ivan: Vidiš li dim? Šumski požar je iznad sela.
Marko: Kanaderi su već tu. Vatrogasci gase od jutra.
Ivan: Hoće li evakuirati kamp?
Marko: Ako vjetar okrene, hoće. Spremimo dokumente za svaki slučaj.
Ivan: Dobro. Napunit ću i boce pitkom vodom.
Marko: I prati upute hitnih službi na radiju.', 'Ivan: Бачиш дим? Лісова пожежа над селом.
Marko: Канадери вже тут. Пожежники гасять з ранку.
Ivan: Чи евакуюють кемпінг?
Marko: Якщо вітер зміниться, евакуюють. Приготуймо документи про всяк випадок.
Ivan: Добре. Наповню й пляшки питною водою.
Marko: І стеж за вказівками екстрених служб по радіо.', 'Діалог «Пожежа поблизу»: «Hoće li evakuirati kamp?» — «Ako vjetar okrene, hoće. Spremimo dokumente za svaki slučaj.», тобто «Якщо вітер зміниться, евакуюють. Приготуймо документи про всяк випадок.».', (select id from public.lessons where id = '88f2e9d5-51e4-5ff4-b18b-b221ac12117d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a7866966-c6f1-5803-8682-315c1b50c4e8', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хотіла б замовити вивезення». Що ви скажете?', null, '["Htjela bih naručiti odvoz.", "Za Split je crveno upozorenje.", "Izgubio sam novčanik."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Я хотіла б замовити вивезення.» — «Htjela bih naručiti odvoz.».', (select id from public.lessons where id = '5ef67da9-21aa-58fa-91c2-d8144333a756'), 'PUBLISHED', 'claude_assessment_v5'),
  ('303bd507-130a-5b4d-a2db-0d6eb062d191', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «метеопопередження»', null, '[]'::jsonb, null, 'meteoalarm', '{}'::text[], null, null, null, '«метеопопередження» — meteoalarm.', (select id from public.lessons where id = '88f2e9d5-51e4-5ff4-b18b-b221ac12117d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('104fe355-fc11-5904-8faa-8a24a7f9b30a', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Скло викидають у зелений контейнер.»', null, '["se", "baca", "u", "zeleni", "Staklo", "spremnik."]'::jsonb, null, 'Staklo se baca u zeleni spremnik.', array['U zeleni spremnik se baca staklo.']::text[], null, null, null, '«Скло викидають у зелений контейнер.» — «Staklo se baca u zeleni spremnik.».', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7d17c6c1-e958-5b38-9472-3d1a7e38e983', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Ми заощаджуємо воду й світло.»', null, '[]'::jsonb, null, 'Štedimo vodu i struju.', '{}'::text[], null, null, null, '«Ми заощаджуємо воду й світло.» — «Štedimo vodu i struju.».', (select id from public.lessons where id = '03c6044d-1ebf-5dee-becb-e4748f65511c'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A2.10 · 12 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m10' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m10 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '30515624-d01a-554f-aeb0-fb274c35a734') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '285d2a27-68a4-5302-afc3-9595d071647a'::uuid then
    raise exception 'Тест a2-m10 прив’язаний не до модуля A2.10 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('30515624-d01a-554f-aeb0-fb274c35a734', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Є, і електронні книги. Позика — на три тижні.", "На вихідних так. Варто поїхати рано вранці.", "Тоді купуй, але спершу порівняй ціни в інтернеті."]'::jsonb, 2, null, '{}'::text[], 'Onda je kupi, ali prvo usporedi cijene na internetu.', null, null, 'Прозвучало: «Onda je kupi, ali prvo usporedi cijene na internetu.» — «Тоді купуй, але спершу порівняй ціни в інтернеті.».', (select id from public.lessons where id = '3fc81316-dca8-5661-88c1-eaf2b61aec07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('79b68694-e26b-5782-87eb-48216b813a5d', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Прошу, аудіокниги — на цій полиці.", "Рибну юшку й домашнє вино. Щиро раджу!", "Гаразд, зараз тобі надішлю."]'::jsonb, 2, null, '{}'::text[], 'Može, poslat ću ti ga odmah.', null, null, 'Прозвучало: «Može, poslat ću ti ga odmah.» — «Гаразд, зараз тобі надішлю.».', (select id from public.lessons where id = '92bd4e0c-f9df-5edb-a65e-9549fe1ef1b8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e8b1e72b-8288-5573-bde8-44c7677b9efd', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Що краще на селі?', 'Grad ili selo?', '["Спокійніше й чистіше повітря", "Частіше ходить автобус", "Більше лікарень"]'::jsonb, 0, null, '{}'::text[], null, 'Mnogi ljudi u Hrvatskoj sele se iz malih mjesta u veće gradove, osobito u Zagreb. U gradu je lakše naći posao, a ima i više škola, bolnica i kafića. Ali život u gradu je skuplji: stanovi su skupi, a promet je gust. Na selu je mirnije i zrak je čišći. Kuće su jeftinije, a ljudi se bolje poznaju. S druge strane, autobus ponekad vozi samo dva puta dnevno, a do najbliže bolnice treba voziti pola sata. Što je bolje? Mislim da to ovisi o tome što vam je u životu važnije.', 'Багато людей у Хорватії переїжджають із маленьких населених пунктів у більші міста, особливо в Загреб. У місті легше знайти роботу, а ще там більше шкіл, лікарень і кафе. Але життя в місті дорожче: квартири дорогі, а рух щільний. На селі спокійніше й повітря чистіше. Будинки дешевші, а люди краще знають одне одного. З іншого боку, автобус іноді їздить лише двічі на день, а до найближчої лікарні треба їхати пів години. Що краще? Я думаю, це залежить від того, що для вас важливіше в житті.', 'Текст «Місто чи село?». Правильна відповідь: «Спокійніше й чистіше повітря».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('53e26bb2-efd2-5a0e-aa37-2498c2f756b7', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li rad od kuće dobar ili loš?', '["Ovisi o poslu. Za mene ima smisla, naime živim daleko.", "Prvo odabereš djelatnost i upišeš obrt u obrtni registar.", "Najbolje je vratiti je u trgovinu, dobijete povratnu naknadu."]'::jsonb, 0, null, '{}'::text[], 'Je li rad od kuće dobar ili loš?', null, null, 'Діалог «Робота з дому: за і проти»: «Je li rad od kuće dobar ili loš?» (Робота з дому — це добре чи погано?) — «Ovisi o poslu. Za mene ima smisla, naime živim daleko.» (Залежить від роботи. Для мене це має сенс, річ у тім, що я живу далеко.).', (select id from public.lessons where id = 'd6b9db92-a933-5d45-8f17-f6e911a97ab1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c1b2b096-e226-5c55-be14-238029b14b41', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što slušaš u autu?', '["Podcast o hrvatskoj povijesti. Nova epizoda izlazi petkom.", "Jesu, prije deset godina. Grad se jako promijenio.", "Deset posto. Preuzeo sam i nove zadatke."]'::jsonb, 0, null, '{}'::text[], 'Što slušaš u autu?', null, null, 'Діалог «Улюблений подкаст»: «Što slušaš u autu?» (Що ти слухаєш в авто?) — «Podcast o hrvatskoj povijesti. Nova epizoda izlazi petkom.» (Подкаст про історію Хорватії. Новий епізод виходить по п’ятницях.).', (select id from public.lessons where id = '92bd4e0c-f9df-5edb-a65e-9549fe1ef1b8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2703ea6e-7f72-52cc-b1fd-54e0d91e7057', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'U redu. Imate li zvučne knjige na hrvatskom?', '["Medicinska sestra je regulirana profesija, pa treba stručno priznavanje.", "Imamo, i e-knjige. Posudba traje tri tjedna.", "Jesmo. Jako smo se posramili, nikad to neću zaboraviti."]'::jsonb, 1, null, '{}'::text[], 'U redu. Imate li zvučne knjige na hrvatskom?', null, null, 'Діалог «У бібліотеці»: «U redu. Imate li zvučne knjige na hrvatskom?» (Гаразд. У вас є аудіокниги хорватською?) — «Imamo, i e-knjige. Posudba traje tri tjedna.» (Є, і електронні книги. Позика — на три тижні.).', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3c1dbd6e-696f-5261-840a-8b0f787ef523', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što vrijedi posjetiti?', '["Дашо, порадь мені якесь місце на вихідні.", "Старе місто й стежку вздовж потічка. І обов’язково скуштуй кремшниту!", "Щиро раджу Самобор. Це прихована перлина біля Загреба."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Daša, preporuči mi neko mjesto za vikend.
Daša: Toplo preporučujem Samobor. To je skriveni dragulj blizu Zagreba.
Darja: Što vrijedi posjetiti?
Daša: Stari grad i šetnicu uz potok. I svakako probaj kremšnitu!
Darja: Je li tamo velika gužva?
Daša: Vikendom da. Isplati se otići rano ujutro.', 'Darja: Дашо, порадь мені якесь місце на вихідні.
Daša: Щиро раджу Самобор. Це прихована перлина біля Загреба.
Darja: Що варто відвідати?
Daša: Старе місто й стежку вздовж потічка. І обов’язково скуштуй кремшниту!
Darja: Там великий натовп?
Daša: На вихідних так. Варто поїхати рано вранці.', 'Діалог «Куди піти у вихідні?»: «Što vrijedi posjetiti?» — «Stari grad i šetnicu uz potok. I svakako probaj kremšnitu!», тобто «Старе місто й стежку вздовж потічка. І обов’язково скуштуй кремшниту!».', (select id from public.lessons where id = '57ba42b9-17e0-5dda-9de1-f0354b45f845'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8f3cb7f1-8312-5a25-9f70-1fc6e03d26ab', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li bolji od prošlog?', '["Набагато цікавіший за попередній. Головна героїня — молода поліцейська.", "Детектив однієї хорватської письменниці. Дія відбувається у Спліті.", "Трохи, але розумію дедалі більше. Він захопливий, не можу відірватися."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Darja, što čitaš?
Darja: Kriminalistički roman jedne hrvatske spisateljice. Radnja se događa u Splitu.
Daša: Je li težak za čitanje na hrvatskom?
Darja: Malo, ali sve više razumijem. Napet je, ne mogu ga ispustiti iz ruku.
Daša: Je li bolji od prošlog?
Darja: Puno je zanimljiviji od prošlog. Glavni lik je mlada policajka.', 'Daša: Дар’є, що ти читаєш?
Darja: Детектив однієї хорватської письменниці. Дія відбувається у Спліті.
Daša: Важко читати хорватською?
Darja: Трохи, але розумію дедалі більше. Він захопливий, не можу відірватися.
Daša: Він кращий за попередній?
Darja: Набагато цікавіший за попередній. Головна героїня — молода поліцейська.', 'Діалог «Що ти читаєш?»: «Je li bolji od prošlog?» — «Puno je zanimljiviji od prošlog. Glavni lik je mlada policajka.», тобто «Набагато цікавіший за попередній. Головна героїня — молода поліцейська.».', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c9afd1d2-3fc6-5da9-9119-7384eef04d24', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Який твій улюблений жанр?». Що ви скажете?', null, '["Preporuči mi neki restoran.", "Koji je tvoj omiljeni žanr?", "Toplo preporučujem ovu knjigu."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Який твій улюблений жанр?» — «Koji je tvoj omiljeni žanr?».', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8f4a177f-c1e8-5bd7-bdfc-8f62b4b5bcfd', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «розділ»', null, '[]'::jsonb, null, 'poglavlje', '{}'::text[], null, null, null, '«розділ» — poglavlje.', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('af423e80-c400-513e-bb7f-fbec8d147584', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Не розповідай мені кінця!»', null, '["mi", "Nemoj", "kraj!", "otkriti"]'::jsonb, null, 'Nemoj mi otkriti kraj!', '{}'::text[], null, null, null, '«Не розповідай мені кінця!» — «Nemoj mi otkriti kraj!».', (select id from public.lessons where id = 'ef11286d-512d-524a-9edc-e760010d1037'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2e185eb4-e7fe-5906-874e-d5babb27d988', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Шукаю квартиру, яка має балкон.»', null, '[]'::jsonb, null, 'Tražim stan koji ima balkon.', '{}'::text[], null, null, null, '«Шукаю квартиру, яка має балкон.» — «Tražim stan koji ima balkon.».', (select id from public.lessons where id = '3fc81316-dca8-5661-88c1-eaf2b61aec07'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A2.11 · 14 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m11' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m11 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'c5e2ffd2-a798-500f-b867-edc53c8cb5a3') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '81b58843-3837-5c58-ab5d-4d16e30620b2'::uuid then
    raise exception 'Тест a2-m11 прив’язаний не до модуля A2.11 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.', estimated_minutes = 7 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('c5e2ffd2-a798-500f-b867-edc53c8cb5a3', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Нам треба роззуватися?", "Що робиш поза сезоном?", "А що їй з’їсти?"]'::jsonb, 0, null, '{}'::text[], 'Trebamo li se izuti?', null, null, 'Прозвучало: «Trebamo li se izuti?» — «Нам треба роззуватися?».', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5e8ee428-7e36-57c3-a936-e410a74aa77b', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дякую, ви дуже гостинні.", "Мамо, не припрошуй її так!", "Згодна. Діти мають знати своє коріння."]'::jsonb, 1, null, '{}'::text[], 'Mama, nemoj je toliko nutkati!', null, null, 'Прозвучало: «Mama, nemoj je toliko nutkati!» — «Мамо, не припрошуй її так!».', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4c3ab1e8-d777-54dc-bf1b-b362a3db4a48', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Далматинський спів а капела, зазвичай вісім голосів.", "Супер, дякую! Запишу все.", "Іноді. Але індичку з млинцями всі розуміють!"]'::jsonb, 0, null, '{}'::text[], 'Dalmatinsko pjevanje, a cappella, obično osam glasova.', null, null, 'Прозвучало: «Dalmatinsko pjevanje, a cappella, obično osam glasova.» — «Далматинський спів а капела, зазвичай вісім голосів.».', (select id from public.lessons where id = 'c71597ab-1dac-5b9d-a304-b389f93a420a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ac3937b5-eb03-5d12-9145-03c319c567f1', v_aid, 4, 'A2', 'reading', 'understand', 'multiple_choice', 'Що можна принести господарям?', 'Kako se ponašati u gostima?', '["Гроші", "Вино, тістечко або квіти", "Нічого"]'::jsonb, 1, null, '{}'::text[], null, 'Kad vas Hrvati pozovu na obiteljski ručak, to je velika stvar. Evo nekoliko savjeta za lijepo ponašanje. Ne dolazite praznih ruku: poklon za domaćina može biti vino, kolač ili cvijeće. Kad uđete u kuću, pitajte trebate li izuti cipele. Puno obitelji ima papuče za goste. Prijatelje pozdravljamo poljupcem u obraz, obično dva puta. Starije ljude persiramo dok nam ne ponude da ih tikamo. Za stolom je pristojno probati sva jela. Ako vam domaćica ponudi još, nije nepristojno reći: «Hvala, sit sam.» Poslije ručka obično pijemo dugu kavu i razgovaramo satima.', 'Коли хорвати запрошують вас на сімейний обід, це важлива подія. Ось кілька порад щодо гарної поведінки. Не приходьте з порожніми руками: подарунком для господаря може бути вино, тістечко чи квіти. Коли зайдете в дім, запитайте, чи треба роззутися. Багато родин мають капці для гостей. Друзів вітають поцілунком у щоку, зазвичай двічі. До старших людей звертаються на «Ви», доки вони не запропонують перейти на «ти». За столом чемно скуштувати всі страви. Якщо господиня пропонує вам ще, не буде нечемно сказати: «Дякую, я наївся.» Після обіду зазвичай довго п''ють каву й розмовляють годинами.', 'Текст «Як поводитися в гостях?». Правильна відповідь: «Вино, тістечко або квіти».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('7ab44d4b-300e-5cd4-9410-62118641da1f', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Rado! Je li staza teška?', '["Obično omotnica s novcem. Takav je običaj.", "Deset posto. Preuzeo sam i nove zadatke.", "Nije, planinarska staza je dobro označena. Pratimo crveno-bijele markacije."]'::jsonb, 2, null, '{}'::text[], 'Rado! Je li staza teška?', null, null, 'Діалог «Похід на Велебіт»: «Rado! Je li staza teška?» (Охоче! Стежка важка?) — «Nije, planinarska staza je dobro označena. Pratimo crveno-bijele markacije.» (Ні, туристична стежка добре позначена. Ідемо за червоно-білим маркуванням.).', (select id from public.lessons where id = 'ab060253-8099-5e7d-bfaa-1b1a7655c229'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b33c274e-80a7-5966-abea-70c0fe336e18', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Može li se kupiti sol iz solane?', '["Za obljetnicu braka roditelja, svake godine u lipnju.", "Može, ninska morska sol je odličan suvenir.", "Trideset posto. Boravišna pristojba se plaća na dolasku."]'::jsonb, 1, null, '{}'::text[], 'Može li se kupiti sol iz solane?', null, null, 'Діалог «Вихідні в Ніні»: «Može li se kupiti sol iz solane?» (А можна купити сіль із солеварні?) — «Može, ninska morska sol je odličan suvenir.» (Можна, нінська морська сіль — чудовий сувенір.).', (select id from public.lessons where id = '185cee8e-46a7-58b2-bc82-166ba74dc272'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0a751ba7-7465-5515-b0a7-fe7553bf0fcc', v_aid, 7, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Moja mama dolazi u Zagreb na jedan dan. Što da joj pokažem?', '["Točno. I ne zaboravi potpis.", "Prvo odabereš djelatnost i upišeš obrt u obrtni registar.", "Počnite na tržnici Dolac, pa uspinjačom na Gornji grad."]'::jsonb, 2, null, '{}'::text[], 'Moja mama dolazi u Zagreb na jedan dan. Što da joj pokažem?', null, null, 'Діалог «Загреб за один день»: «Moja mama dolazi u Zagreb na jedan dan. Što da joj pokažem?» (Моя мама приїжджає до Загреба на один день. Що їй показати?) — «Počnite na tržnici Dolac, pa uspinjačom na Gornji grad.» (Почніть із ринку Долац, а потім фунікулером на Верхнє місто.).', (select id from public.lessons where id = 'a312ce34-22d7-56e3-a38e-106205ee21c0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d64c7705-cc06-5bd3-9610-7d1a8a99f0b7', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kada je ovdje berba grožđa?', '["Так у Славонії заведено. Увечері прийдуть тамбураші.", "У вересні. Приїжджайте тоді, побачите ілоцький винний льох.", "Схоже, але менший. Спів клапи — у списку ЮНЕСКО."]'::jsonb, 1, null, '{}'::text[], null, 'Domaćica: Dobro došli! Izvolite domaću kobasicu iz pušnice i bakin kulen.
Ivan: Hvala, jako ste gostoljubivi.
Domaćica: Tako je to u Slavoniji. Navečer dolaze tamburaši.
Ivan: Kada je ovdje berba grožđa?
Domaćica: U rujnu. Dođite onda, vidjet ćete iločki vinski podrum.
Ivan: Hvala, sigurno ćemo doći!', 'Domaćica: Ласкаво просимо! Прошу, домашня ковбаса з коптильні й бабусин кулен.
Ivan: Дякую, ви дуже гостинні.
Domaćica: Так у Славонії заведено. Увечері прийдуть тамбураші.
Ivan: Коли тут збір винограду?
Domaćica: У вересні. Приїжджайте тоді, побачите ілоцький винний льох.
Ivan: Дякую, обов’язково приїдемо!', 'Діалог «На салаші»: «Kada je ovdje berba grožđa?» — «U rujnu. Dođite onda, vidjet ćete iločki vinski podrum.», тобто «У вересні. Приїжджайте тоді, побачите ілоцький винний льох.».', (select id from public.lessons where id = '4bd3a563-65f6-596c-8f20-aabce6c7811f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b1f143da-7e07-5564-aa08-9e91653cf579', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Znaš li da Hrvatska ima puno nematerijalne baštine?', '["Важливо зберігати такі звичаї.", "І Сіньська алка, старовинний лицарський турнір. Щосерпня.", "Я знаю про пазьке мереживо. Його передають з покоління в покоління."]'::jsonb, 2, null, '{}'::text[], null, 'Ivan: Znaš li da Hrvatska ima puno nematerijalne baštine?
Darja: Znam za pašku čipku. Prenosi se s koljena na koljeno.
Ivan: I sinjska alka, stari viteški turnir. Svakog kolovoza.
Darja: Kod nas je vez, ukrajinska vezena košulja.
Ivan: Važno je očuvati takve običaje.
Darja: Slažem se. Djeca trebaju znati svoje korijene.', 'Ivan: Ти знаєш, що Хорватія має багато нематеріальної спадщини?
Darja: Я знаю про пазьке мереживо. Його передають з покоління в покоління.
Ivan: І Сіньська алка, старовинний лицарський турнір. Щосерпня.
Darja: У нас вишивка, українська вишиванка.
Ivan: Важливо зберігати такі звичаї.
Darja: Згодна. Діти мають знати своє коріння.', 'Діалог «Спадщина»: «Znaš li da Hrvatska ima puno nematerijalne baštine?» — «Znam za pašku čipku. Prenosi se s koljena na koljeno.», тобто «Я знаю про пазьке мереживо. Його передають з покоління в покоління.».', (select id from public.lessons where id = 'c71597ab-1dac-5b9d-a304-b389f93a420a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a465fd29-39aa-5427-b8ba-bff69d7d4ee6', v_aid, 10, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Де тут можна займатися скелелазінням?». Що ви скажете?', null, '["Važno je očuvati stare običaje.", "Ovdje je svježi zrak i mir.", "Gdje se ovdje može slobodno penjati?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Де тут можна займатися скелелазінням?» — «Gdje se ovdje može slobodno penjati?».', (select id from public.lessons where id = '185cee8e-46a7-58b2-bc82-166ba74dc272'), 'PUBLISHED', 'claude_assessment_v5'),
  ('847ce79b-184d-5112-8f4a-48b970c50f4c', v_aid, 11, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Що показати мамі в Загребі?». Що ви скажете?', null, '["Što da pokažem mami u Zagrebu?", "Večeras je nastup klape.", "Kupila sam licitarsko srce za uspomenu."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Що показати мамі в Загребі?» — «Što da pokažem mami u Zagrebu?».', (select id from public.lessons where id = 'a312ce34-22d7-56e3-a38e-106205ee21c0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5a33cfab-1aba-5f3f-abf1-2a1a67e43d2c', v_aid, 12, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «свіжування свині (зимове свято)»', null, '[]'::jsonb, null, 'svinjokolja', '{}'::text[], null, null, null, '«свіжування свині (зимове свято)» — svinjokolja.', (select id from public.lessons where id = '4bd3a563-65f6-596c-8f20-aabce6c7811f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ddbed3c2-8b73-5df4-a75d-d1fe901e6274', v_aid, 13, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Вуковар лежить на Дунаї.»', null, '["Vukovar", "na", "Dunavu.", "leži"]'::jsonb, null, 'Vukovar leži na Dunavu.', array['Na Dunavu leži Vukovar.']::text[], null, null, null, '«Вуковар лежить на Дунаї.» — «Vukovar leži na Dunavu.».', (select id from public.lessons where id = '4bd3a563-65f6-596c-8f20-aabce6c7811f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6dc80eab-9981-592d-adc8-0cd95fae1f5b', v_aid, 14, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я хотіла б скуштувати істрійську манештру.»', null, '[]'::jsonb, null, 'Htjela bih probati istarsku maneštru.', '{}'::text[], null, null, null, '«Я хотіла б скуштувати істрійську манештру.» — «Htjela bih probati istarsku maneštru.».', (select id from public.lessons where id = 'df44c302-d9be-51e9-9c3f-a5faf4ca04a6'), 'PUBLISHED', 'claude_assessment_v5');
