-- Перевірка модуля A2.12 · 12 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m12' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m12 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'c3109a2b-ba06-527a-be5b-22e9c4c72ce5') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '5b885d2c-55ee-5635-91be-a4746da43999'::uuid then
    raise exception 'Тест a2-m12 прив’язаний не до модуля A2.12 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('c3109a2b-ba06-527a-be5b-22e9c4c72ce5', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добрий день, мене цікавить страхування домашнього майна.", "Так, коли отримаю новий паспорт. І принести копію службовцю.", "Дуже. Мені бракує друзів і нашого хліба."]'::jsonb, 1, null, '{}'::text[], 'Moram, kad dobijem novu putovnicu. I službeniku donijeti presliku.', null, null, 'Прозвучало: «Moram, kad dobijem novu putovnicu. I službeniku donijeti presliku.» — «Так, коли отримаю новий паспорт. І принести копію службовцю.».', (select id from public.lessons where id = '5e298915-e179-5d58-bca0-6531c7b43a46'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a51d5ed3-35c7-54a7-acef-362312df44c2', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Вони змішують мови?", "Розумію. Удома він говорить українською?", "А що тобі не подобається?"]'::jsonb, 1, null, '{}'::text[], 'Razumijem. Govori li kod kuće ukrajinski?', null, null, 'Прозвучало: «Razumijem. Govori li kod kuće ukrajinski?» — «Розумію. Удома він говорить українською?».', (select id from public.lessons where id = '56d06c34-2631-5ca9-a3a3-b0df910556dc'), 'PUBLISHED', 'claude_assessment_v5'),
  ('842e0533-8b9b-57be-9e14-aa21d6c8107c', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Що Дар’я поклала в посилку?', 'Paket za Ukrajinu', '["Каву, шоколад, олію й теплу кофту", "Ліки", "Гроші"]'::jsonb, 0, null, '{}'::text[], null, 'Darja: Mama, danas sam ti poslala paket kurirskom službom.
Mama: Hvala, dušo! Što si stavila unutra?
Darja: Kavu, čokoladu, maslinovo ulje i toplu majicu za tatu. Morala sam ispuniti carinsku deklaraciju i napisati sadržaj paketa.
Mama: A koliko si platila dostavu?
Darja: Težina paketa je pet kilograma, pa je bilo trideset eura. Rok dostave je oko tjedan dana.
Mama: Kako ću znati gdje je paket?
Darja: Poslat ću ti broj za praćenje, pa možeš pratiti pošiljku na internetu.
Mama: Super. A novac si mi poslala?
Darja: Jesam, preko aplikacije za plaćanje. Naknada za prijenos je mala, a novac stigne odmah.', 'Дар''я: Мамо, сьогодні я надіслала тобі посилку кур''єрською службою.
Мама: Дякую, доню! Що ти поклала всередину?
Дар''я: Каву, шоколад, оливкову олію й теплу кофту для тата. Мені довелося заповнити митну декларацію і написати вміст посилки.
Мама: А скільки ти заплатила за доставку?
Дар''я: Вага посилки п''ять кілограмів, тож вийшло тридцять євро. Термін доставки – близько тижня.
Мама: Як я знатиму, де посилка?
Дар''я: Я надішлю тобі номер для відстеження, і ти зможеш стежити за відправленням в інтернеті.
Мама: Чудово. А гроші ти мені надіслала?
Дар''я: Так, через платіжний застосунок. Комісія за переказ невелика, а гроші приходять одразу.', 'Текст «Посилка додому». Правильна відповідь: «Каву, шоколад, олію й теплу кофту».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('0ec8a5d5-9c45-57e6-86f6-8a54ad73ed59', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Darja, što je najviše drukčije u Hrvatskoj nego u Ukrajini?', '["Ritam života. Ovdje je sporiji, ljudi su opušteniji.", "Slomila sam je na skijanju prošli mjesec.", "Pred Božić. Onda su zimski školski praznici."]'::jsonb, 0, null, '{}'::text[], 'Darja, što je najviše drukčije u Hrvatskoj nego u Ukrajini?', null, null, 'Діалог «Що інакше?»: «Darja, što je najviše drukčije u Hrvatskoj nego u Ukrajini?» (Дар’є, що найбільше відрізняється в Хорватії від України?) — «Ritam života. Ovdje je sporiji, ljudi su opušteniji.» (Ритм життя. Тут він повільніший, люди розслабленіші.).', (select id from public.lessons where id = '0465a2cd-1da9-5a6e-a47d-434fc8bee342'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c1e027a0-ff60-5196-b0ff-56664106753e', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što vas je najviše dirnulo?', '["Solidarnost. Susjedi su donirali djeci odjeću i igračke.", "Prodavač je bio neljubazan. To je neprihvatljivo.", "Malo povučen, ali iskren i marljiv."]'::jsonb, 0, null, '{}'::text[], 'Što vas je najviše dirnulo?', null, null, 'Діалог «Чому я волонтерю»: «Što vas je najviše dirnulo?» (Що вас найбільше зворушило?) — «Solidarnost. Susjedi su donirali djeci odjeću i igračke.» (Солідарність. Сусіди подарували дітям одяг та іграшки.).', (select id from public.lessons where id = '55fdd530-ac46-5ba9-a5de-9fd5944b0c8c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8981cc13-6cd1-53f6-a27c-b3eef09c63dd', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Miješaju li jezike?', '["Na vratima učionice. Samo ispuniš upisnicu.", "Hoće. Na kraju piše „ovjereno“, s pečatom i potpisom.", "Ponekad. Sin polako zaboravlja ukrajinski, zato mu čitam svake večeri."]'::jsonb, 2, null, '{}'::text[], 'Miješaju li jezike?', null, null, 'Діалог «Дві мови»: «Miješaju li jezike?» (Вони змішують мови?) — «Ponekad. Sin polako zaboravlja ukrajinski, zato mu čitam svake večeri.» (Іноді. Син потроху забуває українську, тому я читаю йому щовечора.).', (select id from public.lessons where id = '56d06c34-2631-5ca9-a3a3-b0df910556dc'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7c535696-3eeb-5b3f-84af-c7220bdb4cef', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kako šalješ novac roditeljima?', '["Так, це застосунок мого банку. Я завжди отримую підтвердження.", "Через платіжний застосунок. Гроші надходять за кілька хвилин.", "Невелика, але я стежу за валютним курсом. Батьки отримують гривні."]'::jsonb, 1, null, '{}'::text[], null, 'Ivan: Kako šalješ novac roditeljima?
Darja: Preko aplikacije za plaćanje. Novac stiže za nekoliko minuta.
Ivan: A naknada za prijenos?
Darja: Mala, ali pazim na devizni tečaj. Roditelji primaju hrivnje.
Ivan: Je li to sigurno?
Darja: Jest, aplikacija je od moje banke. Uvijek dobijem potvrdu.', 'Ivan: Як ти надсилаєш гроші батькам?
Darja: Через платіжний застосунок. Гроші надходять за кілька хвилин.
Ivan: А комісія за переказ?
Darja: Невелика, але я стежу за валютним курсом. Батьки отримують гривні.
Ivan: Це безпечно?
Darja: Так, це застосунок мого банку. Я завжди отримую підтвердження.', 'Діалог «Переказ»: «Kako šalješ novac roditeljima?» — «Preko aplikacije za plaćanje. Novac stiže za nekoliko minuta.», тобто «Через платіжний застосунок. Гроші надходять за кілька хвилин.».', (select id from public.lessons where id = 'bc5bde26-5065-560b-8877-1302e7048471'), 'PUBLISHED', 'claude_assessment_v5'),
  ('cf9d4b95-0316-5623-9950-3d9966dc249b', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Odjeća, kava i čokolada. Smijem li poslati lijekove?', '["Від п’яти до семи днів. Надішліть мамі номер для відстеження.", "Що в посилці? Вам треба заповнити митну декларацію.", "Деякі ліки не можна, це заборонені предмети."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Dobar dan, htjela bih poslati paket mami u Ukrajinu.
Službenica: Što je u paketu? Trebate ispuniti carinsku deklaraciju.
Darja: Odjeća, kava i čokolada. Smijem li poslati lijekove?
Službenica: Neke lijekove ne smijete, to su zabranjeni predmeti.
Darja: Koliko traje dostava?
Službenica: Pet do sedam dana. Mami pošaljite broj za praćenje.', 'Darja: Добрий день, я хотіла б надіслати посилку мамі в Україну.
Službenica: Що в посилці? Вам треба заповнити митну декларацію.
Darja: Одяг, кава й шоколад. Чи можна надіслати ліки?
Službenica: Деякі ліки не можна, це заборонені предмети.
Darja: Скільки триває доставка?
Službenica: Від п’яти до семи днів. Надішліть мамі номер для відстеження.', 'Діалог «Посилка мамі»: «Odjeća, kava i čokolada. Smijem li poslati lijekove?» — «Neke lijekove ne smijete, to su zabranjeni predmeti.», тобто «Деякі ліки не можна, це заборонені предмети.».', (select id from public.lessons where id = 'bc5bde26-5065-560b-8877-1302e7048471'), 'PUBLISHED', 'claude_assessment_v5'),
  ('de9afaff-de3a-5fc3-9802-1bf17d48f7fa', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хочу віддячити добром». Що ви скажете?', null, '["Kod kuće govorimo ukrajinski.", "Želim vratiti dobrotu.", "Ponosna sam na kćer."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я хочу віддячити добром.» — «Želim vratiti dobrotu.».', (select id from public.lessons where id = '55fdd530-ac46-5ba9-a5de-9fd5944b0c8c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9577f509-d2d5-576a-9a4a-69c356169777', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «новоприбулі»', null, '[]'::jsonb, null, 'novopridošli', '{}'::text[], null, null, null, '«новоприбулі» — novopridošli.', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_v5'),
  ('70a07658-e894-5ac7-b664-c70ad52017d4', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Тут я почуваюся як удома.»', null, '["kao", "kod", "osjećam", "kuće.", "Ovdje", "se"]'::jsonb, null, 'Ovdje se osjećam kao kod kuće.', array['Osjećam se ovdje kao kod kuće.']::text[], null, null, null, '«Тут я почуваюся як удома.» — «Ovdje se osjećam kao kod kuće.».', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_v5'),
  ('68a860b2-58cd-5bba-9e22-0734eb06a03a', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «На відміну від Києва, Спліт маленький.»', null, '[]'::jsonb, null, 'Za razliku od Kijeva, Split je malen.', '{}'::text[], null, null, null, '«На відміну від Києва, Спліт маленький.» — «Za razliku od Kijeva, Split je malen.».', (select id from public.lessons where id = '0465a2cd-1da9-5a6e-a47d-434fc8bee342'), 'PUBLISHED', 'claude_assessment_v5');
