                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('273e2254-ec98-5ec0-8f47-19fc7dab49ef', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Я б відкрила власну справу, маленьку галерею. Малювала б море.", "Можна. Я вам повідомлю, якщо щось зміниться.", "Успіхів! А я відкладаю на права на мотоцикл."]'::jsonb, 2, null, '{}'::text[], 'Sretno! Ja štedim za vozački za motor.', null, null, 'Прозвучало: «Sretno! Ja štedim za vozački za motor.» — «Успіхів! А я відкладаю на права на мотоцикл.».', (select id from public.lessons where id = 'f2760130-fd69-5932-978c-cc424aaefafa'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3d74ed6b-8508-52a6-bddd-000d7c4ce744', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Найважливіше — гарний настрій. Наступного разу — просто неба!", "Супер. Натомість я допоможу тобі з переїздом.", "Я організовую вечірку на день народження Даші. Сюрприз для неї!"]'::jsonb, 1, null, '{}'::text[], 'Super. Zauzvrat ću ti pomoći s preseljenjem.', null, null, 'Прозвучало: «Super. Zauzvrat ću ti pomoći s preseljenjem.» — «Супер. Натомість я допоможу тобі з переїздом.».', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9abc0490-f12e-56b5-9661-145ad9b78a12', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Де вона склала список цілей?', 'Moje novogodišnje odluke', '["У планері", "У телефоні", "На холодильнику"]'::jsonb, 0, null, '{}'::text[], null, 'Svake godine postavim nekoliko ciljeva, ali ih često ne ostvarim. Ove godine želim biti realna. Napravila sam listu ciljeva u planeru. Prvi cilj: do kraja godine položiti ispit iz hrvatskog i dobiti certifikat. Drugi cilj: uštedjeti za ljetovanje, pa ću svaki mjesec staviti sto eura na štednju. Treći cilj je dugoročni plan: jednog dana otvoriti vlastiti posao. Znam da će biti teško, ali neću odustati. Za uspjeh treba motivacija, ali još više ustrajnost. Vidjet ćemo kako će ići!', 'Щороку я ставлю собі кілька цілей, але часто їх не досягаю. Цього року я хочу бути реалісткою. Я склала список цілей у планері. Перша мета: до кінця року скласти іспит з хорватської й отримати сертифікат. Друга мета: заощадити на літню відпустку, тож щомісяця я відкладатиму сто євро. Третя мета – довгостроковий план: одного дня відкрити власну справу. Я знаю, що буде важко, але не здамся. Для успіху потрібна мотивація, але ще більше – наполегливість. Побачимо, як піде!', 'Текст «Мої новорічні рішення». Правильна відповідь: «У планері».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('b61f0e2c-ca65-540c-94c7-16fb200317a7', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ivane, možeš li mi u subotu pričuvati psa?', '["Mogu, osim ako me ne pozovu na posao.", "Prva dva tjedna u kolovozu. Tvrtka je tada zatvorena.", "Pet do sedam dana. Mami pošaljite broj za praćenje."]'::jsonb, 0, null, '{}'::text[], 'Ivane, možeš li mi u subotu pričuvati psa?', null, null, 'Діалог «Допомога за допомогу»: «Ivane, možeš li mi u subotu pričuvati psa?» (Іване, можеш у суботу наглянути за моїм псом?) — «Mogu, osim ako me ne pozovu na posao.» (Можу, хіба що мене не викличуть на роботу.).', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_v5'),
  ('60fbfe81-97f8-5f05-9471-cd8c53d33ce8', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'U redu. Želite li novi termin?', '["Liječnik kaže da neće. Srećom!", "Želim. Ispričavam se zbog otkazivanja u zadnji čas.", "Napiši „Poštovani gospodine Horvat“, ne „Bok“."]'::jsonb, 1, null, '{}'::text[], 'U redu. Želite li novi termin?', null, null, 'Діалог «Скасування в лікаря»: «U redu. Želite li novi termin?» (Гаразд. Бажаєте новий час?) — «Želim. Ispričavam se zbog otkazivanja u zadnji čas.» (Так. Перепрошую за скасування в останню хвилину.).', (select id from public.lessons where id = '0b054356-d4b4-5f6e-b7e9-3dc8f3c9d4ff'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0b148029-7e66-5999-b3b5-3566d1ac9bd8', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mama, možemo li u subotu na izlet?', '["Probat ćemo. Kaput će biti gotov do petka.", "Možemo, pod uvjetom da napišeš zadaću u petak.", "U dvorani škole. Trebamo dugotrajnu hranu i higijenske potrepštine."]'::jsonb, 1, null, '{}'::text[], 'Mama, možemo li u subotu na izlet?', null, null, 'Діалог «Домовляємося з дітьми»: «Mama, možemo li u subotu na izlet?» (Мамо, можна нам у суботу на екскурсію?) — «Možemo, pod uvjetom da napišeš zadaću u petak.» (Можна, за умови, що ти зробиш домашнє в п’ятницю.).', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_v5'),
  ('094e0676-a91b-58ba-a082-ca06f7ee94de', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Naravno. Gdje je blagajna?', '["Біля входу, праворуч від роздягалень.", "Не можна, шапочка обов’язкова. Вам довелося б купити її в касі.", "Для дітей до шести років є виняток. І прошу дотримуватися правил."]'::jsonb, 0, null, '{}'::text[], null, 'Ivan: Oprostite, smijem li ući bez kape?
Spasilac: Ne smijete, kapa je obvezna. Morali biste je kupiti na blagajni.
Ivan: A djeca?
Spasilac: Za djecu do šest godina postoji iznimka. I molim da se pridržavate pravila.
Ivan: Naravno. Gdje je blagajna?
Spasilac: Na ulazu, desno od svlačionica.', 'Ivan: Перепрошую, мені можна зайти без шапочки?
Spasilac: Не можна, шапочка обов’язкова. Вам довелося б купити її в касі.
Ivan: А діти?
Spasilac: Для дітей до шести років є виняток. І прошу дотримуватися правил.
Ivan: Звісно. Де каса?
Spasilac: Біля входу, праворуч від роздягалень.', 'Діалог «Правила в басейні»: «Naravno. Gdje je blagajna?» — «Na ulazu, desno od svlačionica.», тобто «Біля входу, праворуч від роздягалень.».', (select id from public.lessons where id = 'b8615bf1-2cc2-5cc1-b89a-ed065a4b9c28'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5175c541-321b-5044-9202-7e18b8d0603c', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ambiciozno! Kako ćeš ostvariti cilj s ispitom?', '["Щодня по пів години. За прогресом стежу в зошиті.", "Побачимо. Потрібна наполегливість.", "У мене три цілі. Складу іспит B1, заощаджу на море й поміняю роботу."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Darja, imaš li novogodišnju odluku?
Darja: Imam tri cilja. Položit ću ispit B1, uštedjet ću za more i promijenit ću posao.
Daša: Ambiciozno! Kako ćeš ostvariti cilj s ispitom?
Darja: Svaki dan po pola sata. Napredak pratim u bilježnici.
Daša: Samo nemoj odustati u veljači!
Darja: Vidjet ćemo. Treba ustrajnosti.', 'Daša: Дар’є, у тебе є новорічна обіцянка?
Darja: У мене три цілі. Складу іспит B1, заощаджу на море й поміняю роботу.
Daša: Амбітно! Як ти досягнеш мети з іспитом?
Darja: Щодня по пів години. За прогресом стежу в зошиті.
Daša: Тільки не здайся в лютому!
Darja: Побачимо. Потрібна наполегливість.', 'Діалог «Новорічні обіцянки»: «Ambiciozno! Kako ćeš ostvariti cilj s ispitom?» — «Svaki dan po pola sata. Napredak pratim u bilježnici.», тобто «Щодня по пів години. За прогресом стежу в зошиті.».', (select id from public.lessons where id = 'f2760130-fd69-5932-978c-cc424aaefafa'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b250c34c-e81d-5f22-8283-faf360dc9577', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «У разі, якщо я запізнюся, починайте без мене». Що ви скажете?', null, '["Moj cilj je promijeniti posao.", "Štedimo za novi auto.", "U slučaju da kasnim, počnite bez mene."]'::jsonb, 2, null, '{}'::text[], null, null, null, '«У разі, якщо я запізнюся, починайте без мене.» — «U slučaju da kasnim, počnite bez mene.».', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_v5'),
  ('36a5dec1-199f-5b6e-a4a7-5b851d932969', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «недосяжний»', null, '[]'::jsonb, null, 'nedostižan', '{}'::text[], null, null, null, '«недосяжний» — nedostižan.', (select id from public.lessons where id = '00cd6ab0-29c4-5eab-94a4-5319d76fbce4'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4010d1da-857d-517b-a59a-920bf8ca1f6b', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Якби я могла, я б подорожувала.»', null, '["mogla,", "bih", "bih.", "putovala", "Kad"]'::jsonb, null, 'Kad bih mogla, putovala bih.', '{}'::text[], null, null, null, '«Якби я могла, я б подорожувала.» — «Kad bih mogla, putovala bih.».', (select id from public.lessons where id = '00cd6ab0-29c4-5eab-94a4-5319d76fbce4'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ca840f47-4357-5c92-b4d5-53321a41930d', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Вибач, у мене дещо непередбачене.»', null, '[]'::jsonb, null, 'Oprosti, iskrsnulo mi je nešto.', '{}'::text[], null, null, null, '«Вибач, у мене дещо непередбачене.» — «Oprosti, iskrsnulo mi je nešto.».', (select id from public.lessons where id = '0b054356-d4b4-5f6e-b7e9-3dc8f3c9d4ff'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A2.14 · 12 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m14' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m14 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'ccd64b22-ecea-5ab7-a8a7-d580735453d5') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from 'a22f1345-0879-5cde-ad47-4a76556dcf7e'::uuid then
    raise exception 'Тест a2-m14 прив’язаний не до модуля A2.14 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('ccd64b22-ecea-5ab7-a8a7-d580735453d5', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Як було в лікаря?", "Як мені про щось попросити?", "А офіційний лист? Що інакше?"]'::jsonb, 0, null, '{}'::text[], 'Kako je bilo kod liječnika?', null, null, 'Прозвучало: «Kako je bilo kod liječnika?» — «Як було в лікаря?».', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a8d4a986-d9e0-5c81-a2d4-a0c44f161309', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Які зими в Горському Котарі?", "А через п’ять років?", "Що ви плануєте надалі?"]'::jsonb, 2, null, '{}'::text[], 'Što namjeravate ubuduće?', null, null, 'Прозвучало: «Što namjeravate ubuduće?» — «Що ви плануєте надалі?».', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0054ff7d-4fc7-5dbe-ad02-6743514db283', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Скільки коштує вхід?', 'Festival u Zagrebu', '["Вхід безкоштовний", "П’ять євро", "Десять євро"]'::jsonb, 0, null, '{}'::text[], null, 'Ovog vikenda u Zagrebu je Festival hrane i vina. Na Trgu bana Jelačića bit će više od pedeset štandova s domaćim proizvodima iz cijele Hrvatske. Posjetitelji će moći probati sireve, pršut, med i vina iz Istre, Slavonije i Dalmacije. Za djecu će biti predstave i društvene igre, a navečer koncert tamburaša i klape. Festival je otvoren od petka do nedjelje, od 10 do 22 sata, a ulaz je besplatan. Prema najavi, doći će više od dvadeset tisuća posjetitelja. Ako vrijeme bude loše, festival se seli na tržnicu Dolac.', 'Цими вихідними в Загребі — Фестиваль їжі й вина. На площі бана Єлачича буде понад п’ятдесят стендів із домашніми продуктами з усієї Хорватії. Відвідувачі зможуть скуштувати сири, пршут, мед і вина з Істрії, Славонії та Далмації. Для дітей будуть вистави й настільні ігри, а ввечері — концерт тамбурашів і клапи. Фестиваль працює з п’ятниці до неділі, з 10 до 22 години, а вхід безкоштовний. За анонсом, прийде понад двадцять тисяч відвідувачів. Якщо погода буде погана, фестиваль переїде на ринок Долац.', 'Текст «Фестиваль у Загребі». Правильна відповідь: «Вхід безкоштовний».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('da56913a-a67f-5fe2-ac2f-35515f913476', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Rodni list imam samo na ukrajinskom. Što točno trebate?', '["Ovjereni prijevod. Možete mi ga donijeti sutra.", "Volio bih naučiti svirati gitaru.", "Kupila bih vikendicu na otoku i putovala bih oko svijeta."]'::jsonb, 0, null, '{}'::text[], 'Rodni list imam samo na ukrajinskom. Što točno trebate?', null, null, 'Діалог «В установі»: «Rodni list imam samo na ukrajinskom. Što točno trebate?» (Свідоцтво в мене лише українською. Що саме вам потрібно?) — «Ovjereni prijevod. Možete mi ga donijeti sutra.» (Засвідчений переклад. Можете принести мені його завтра.).', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f1259c45-8a5a-53e1-98ad-8f1102abd148', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Jesam li dobro razumjela: sutra prijevod, i onda je riješeno?', '["Pisalo je u kalendaru. Kod nas se imendan rijetko slavi.", "Točno. To je zadnji korak.", "Prodavač je bio neljubazan. To je neprihvatljivo."]'::jsonb, 1, null, '{}'::text[], 'Jesam li dobro razumjela: sutra prijevod, i onda je riješeno?', null, null, 'Діалог «В установі»: «Jesam li dobro razumjela: sutra prijevod, i onda je riješeno?» (Чи правильно я зрозуміла: завтра переклад, і тоді все вирішено?) — «Točno. To je zadnji korak.» (Саме так. Це останній крок.).', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('57942b09-c785-50ef-8c11-51edd59b7acb', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'A službeno pismo? Što je drukčije?', '["Ponekad. Sin polako zaboravlja ukrajinski, zato mu čitam svake večeri.", "Obično omotnica s novcem. Takav je običaj.", "Obraćanje: „Poštovana gospođo“. Ton pisma mora biti ljubazan."]'::jsonb, 2, null, '{}'::text[], 'A službeno pismo? Što je drukčije?', null, null, 'Діалог «Офіційний лист»: «A službeno pismo? Što je drukčije?» (А офіційний лист? Що інакше?) — «Obraćanje: „Poštovana gospođo“. Ton pisma mora biti ljubazan.» (Звертання: «Шановна пані». Тон листа має бути ввічливим.).', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9aa51595-f012-5ebb-ad25-69c0bddde107', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Daša, pišem pismo prijateljici u Kijev. Kako da počnem na hrvatskom?', '["«Я дуже сумую за тобою, не можу дочекатися зустрічі. Щирі вітання!»", "І P. S. — передавай вітання мамі!", "«Дорога Олено». Потім напиши новини, коротко."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Daša, pišem pismo prijateljici u Kijev. Kako da počnem na hrvatskom?
Daša: „Draga Olena“. Onda napiši novosti, ukratko.
Darja: A na kraju?
Daša: „Jako mi nedostaješ, jedva čekam da se vidimo. Puno pozdrava!“
Darja: I P. S. — pozdravi mamu!
Daša: Savršeno! Olena će se jako obradovati.', 'Darja: Дашо, я пишу лист подрузі до Києва. Як почати хорватською?
Daša: «Дорога Олено». Потім напиши новини, коротко.
Darja: А наприкінці?
Daša: «Я дуже сумую за тобою, не можу дочекатися зустрічі. Щирі вітання!»
Darja: І P. S. — передавай вітання мамі!
Daša: Чудово! Олена дуже зрадіє.', 'Діалог «Лист подрузі»: «Daša, pišem pismo prijateljici u Kijev. Kako da počnem na hrvatskom?» — «„Draga Olena“. Onda napiši novosti, ukratko.», тобто ««Дорога Олено». Потім напиши новини, коротко.».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('aeab2467-b15b-5782-845d-9f53bf62767a', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kad pogledaš unatrag, što ti je najveće postignuće?', '["Були, але я навчилася на помилках. Ні про що не шкодую.", "Діти. Вони адаптувалися й говорять двома мовами.", "Сподіваюся на мир. Кожен день — маленький крок уперед."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Kad pogledaš unatrag, što ti je najveće postignuće?
Darja: Djeca. Prilagodila su se i govore dva jezika.
Daša: A neuspjesi?
Darja: Bilo ih je, ali naučila sam iz pogrešaka. Ne žalim ni za čim.
Daša: Za pet godina?
Darja: Nadam se miru. Svaki dan je mali korak naprijed.', 'Daša: Коли озираєшся назад, що твоє найбільше досягнення?
Darja: Діти. Вони адаптувалися й говорять двома мовами.
Daša: А невдачі?
Darja: Були, але я навчилася на помилках. Ні про що не шкодую.
Daša: А через п’ять років?
Darja: Сподіваюся на мир. Кожен день — маленький крок уперед.', 'Діалог «Підсумок»: «Kad pogledaš unatrag, što ti je najveće postignuće?» — «Djeca. Prilagodila su se i govore dva jezika.», тобто «Діти. Вони адаптувалися й говорять двома мовами.».', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bbb135a3-e523-5aae-9932-a3351a1e46f7', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Чи правильно я зрозуміла?». Що ви скажете?', null, '["Jedva čekam da se vidimo.", "Jesam li dobro razumjela?", "Za pet godina vidim se u vlastitom stanu."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Чи правильно я зрозуміла?» — «Jesam li dobro razumjela?».', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bfaf88e1-63fe-58fb-be6d-f2982eca96fd', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «молодість»', null, '[]'::jsonb, null, 'mladost', '{}'::text[], null, null, null, '«молодість» — mladost.', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0467e4bf-c688-5091-9506-dddef5d8a938', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я дуже сумую за тобою.»', null, '["nedostaješ.", "Jako", "mi"]'::jsonb, null, 'Jako mi nedostaješ.', array['Nedostaješ mi jako.']::text[], null, null, null, '«Я дуже сумую за тобою.» — «Jako mi nedostaješ.».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('084b45a9-5c42-504b-9030-723a679bed62', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я була б вам вдячна за відповідь.»', null, '[]'::jsonb, null, 'Bila bih Vam zahvalna na odgovoru.', '{}'::text[], null, null, null, '«Я була б вам вдячна за відповідь.» — «Bila bih Vam zahvalna na odgovoru.».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

-- Перевірка середини рівня A2 · 30 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-mid' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-mid — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'baa356cc-407c-55c5-9c92-2f88034dbf53') then return; end if;  -- уже оновлено
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Середина рівня (модулі A2.1–A2.7): 30 завдань на 4 навички. ~15 хв.', estimated_minutes = 15 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('baa356cc-407c-55c5-9c92-2f88034dbf53', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Спробуємо. Пальто буде готове до п’ятниці.", "Буде. Наприкінці написано «засвідчено», з печаткою й підписом.", "Кравець поруч зі шевцем, навпроти."]'::jsonb, 2, null, '{}'::text[], 'Krojač je pored postolara, preko puta.', null, null, 'Прозвучало: «Krojač je pored postolara, preko puta.» — «Кравець поруч зі шевцем, навпроти.».', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_v5'),
  ('aa2a2dce-a711-5628-952b-bdf64ebd83ff', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Правда. Лише татів старий альбом лишився таким самим.", "Це конфлікт поколінь. Але все постійно змінюється.", "Одного разу ми всім класом прогуляли урок історії."]'::jsonb, 0, null, '{}'::text[], 'Istina. Samo je tatin stari album ostao isti.', null, null, 'Прозвучало: «Istina. Samo je tatin stari album ostao isti.» — «Правда. Лише татів старий альбом лишився таким самим.».', (select id from public.lessons where id = 'b22c7dff-1657-5dad-94a6-5d059e346da8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('aedb78eb-401c-5c94-9192-c827bd863dff', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ти маєш право на вихідну допомогу?", "Чи мушу я виписувати рахунок кожному покупцеві?", "Чи можемо перенести строк на понеділок?"]'::jsonb, 0, null, '{}'::text[], 'Imaš li pravo na otpremninu?', null, null, 'Прозвучало: «Imaš li pravo na otpremninu?» — «Ти маєш право на вихідну допомогу?».', (select id from public.lessons where id = '3ceb812b-6a68-5204-beba-52e0cb3031ad'), 'PUBLISHED', 'claude_assessment_v5'),
  ('019b0307-a073-59a0-bf42-946ec862fefe', v_aid, 4, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так, на стрижку о десятій. Просто трохи підрівняйте.", "Нотаріальний збір установлений, залежить від кількості сторінок.", "Не треба. Ви підписуєте особисто, а я засвідчую підпис."]'::jsonb, 2, null, '{}'::text[], 'Ne treba. Vi potpisujete osobno, a ja ovjeravam potpis.', null, null, 'Прозвучало: «Ne treba. Vi potpisujete osobno, a ja ovjeravam potpis.» — «Не треба. Ви підписуєте особисто, а я засвідчую підпис.».', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c956a67b-ef16-512e-9a66-3a5126499f30', v_aid, 5, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Є. Зателефоную в страхову компанію й оплачу збитки.", "Передай бабусі вітання від мене. Тримайся!", "Добре, я тобі пробачаю. Я теж на тебе кричала."]'::jsonb, 2, null, '{}'::text[], 'Dobro, opraštam ti. I ja sam vikala na tebe.', null, null, 'Прозвучало: «Dobro, opraštam ti. I ja sam vikala na tebe.» — «Добре, я тобі пробачаю. Я теж на тебе кричала.».', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_v5'),
  ('46ad8715-be35-50e6-81af-f64bec658400', v_aid, 6, 'A2', 'reading', 'understand', 'multiple_choice', 'Що потрібно надіслати до середи?', 'Poruka razrednice', '["Фото", "Підписану згоду батьків", "Гроші"]'::jsonb, 1, null, '{}'::text[], null, 'Poštovani roditelji,
podsjećam vas da je u petak izlet razreda na Plitvička jezera. Polazak je u 7:30 ispred škole, a povratak oko 18 sati. Djeca trebaju ponijeti marendu, vodu i udobnu obuću. Za izlet je potrebna potpisana suglasnost roditelja. Molim vas da suglasnost pošaljete do srijede. Također vas obavještavam da su ocjene iz prvog polugodišta upisane u e-Dnevnik. Neki učenici imaju izostanke koji još nisu opravdani. Liječničku ispričnicu treba donijeti u roku od tjedan dana.
Srdačan pozdrav,
razrednica Maja Božić', 'Шановні батьки!
Нагадую вам, що в п''ятницю класна екскурсія на Плітвицькі озера. Відправлення о 7:30 перед школою, а повернення близько 18 години. Діти мають узяти з собою перекус, воду й зручне взуття. Для екскурсії потрібна підписана згода батьків. Прошу вас надіслати згоду до середи. Також повідомляю вам, що оцінки за перше півріччя внесено в «e-Dnevnik». Деякі учні мають пропуски, які ще не виправдано. Довідку від лікаря треба принести протягом тижня.
З повагою,
класна керівниця Мая Божич', 'Текст «Повідомлення від класної керівниці». Правильна відповідь: «Підписану згоду батьків».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('51e3122d-d7ee-5aa6-a745-ba515ea9d65f', v_aid, 7, 'A2', 'reading', 'understand', 'multiple_choice', 'Чого хоче Дар’я, якщо проблему не розв’яжуть?', 'Prigovor na apartman', '["Новий ключ", "Повернути передоплату", "Знижку на вечерю"]'::jsonb, 1, null, '{}'::text[], null, 'Poštovani gospodine Babiću,
jučer smo stigli u vaš apartman u Makarskoj. Lokacija je odlična i plaža je blizu, ali imamo nekoliko problema. Klima-uređaj ne funkcionira, a u kupaonici curi voda iz tuš kabine. Također, na prozoru nema mrežice protiv komaraca, pa noću ne možemo spavati. U oglasu je pisalo da je doručak uključen, ali danas ujutro nitko nije došao. Molim vas da riješite problem što prije ili da nas premjestite u drugi apartman. Ako to nije moguće, htjeli bismo dobiti povrat predujma.
Unaprijed hvala,
Darja Kovalenko', 'Шановний пане Бабичу!
Учора ми приїхали до ваших апартаментів у Макарській. Розташування чудове, і пляж поруч, але в нас є кілька проблем. Кондиціонер не працює, а у ванній з душової кабіни тече вода. Також на вікні немає сітки від комарів, тож уночі ми не можемо спати. В оголошенні було написано, що сніданок включено, але сьогодні вранці ніхто не прийшов. Прошу вас якнайшвидше розв''язати проблему або переселити нас в інші апартаменти. Якщо це неможливо, ми хотіли б отримати назад передоплату.
Заздалегідь дякую,
Дар''я Коваленко', 'Текст «Скарга на апартаменти». Правильна відповідь: «Повернути передоплату».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('653ef7de-1560-5e76-a469-233a7d02998d', v_aid, 8, 'A2', 'reading', 'understand', 'multiple_choice', 'Що сказала лікарка?', 'Olena se prehladila', '["Що треба в лікарню", "Що вона здорова", "Що в неї запалення горла"]'::jsonb, 2, null, '{}'::text[], null, 'Prošli tjedan Olena se jako prehladila. Imala je temperaturu, boljelo ju je grlo i stalno je kašljala. Prva dva dana pila je čaj s medom i ležala u krevetu, ali nije joj bilo bolje. U srijedu je nazvala svoju liječnicu i naručila se na pregled. Liječnica ju je pregledala i rekla da ima upalu grla. Dala joj je recept za antibiotik i bolovanje do petka. Olena je kupila lijek u ljekarni i uzimala ga je dva puta dnevno. U subotu se već osjećala puno bolje. Sljedeći put odmah će nazvati liječnicu.', 'Минулого тижня Олена сильно застудилася. У неї була температура, боліло горло, і вона постійно кашляла. Перші два дні вона пила чай із медом і лежала в ліжку, але їй не ставало краще. У середу вона зателефонувала своїй лікарці й записалася на огляд. Лікарка оглянула її й сказала, що в неї запалення горла. Вона дала їй рецепт на антибіотик і лікарняний до п’ятниці. Олена купила ліки в аптеці й приймала їх двічі на день. У суботу вона почувалася вже набагато краще. Наступного разу вона одразу зателефонує лікарці.', 'Текст «Олена застудилася». Правильна відповідь: «Що в неї запалення горла».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('74cb5a2d-38aa-5a01-b862-49d7bdfd0885', v_aid, 9, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan. Što se dogodilo?', '["Tražila sam i našla sam! Dobila sam ponudu u Splitu.", "Voda je procurila kroz strop u našoj kupaonici.", "Petnaestog svibnja, idemo u Krapinu."]'::jsonb, 1, null, '{}'::text[], 'Dobar dan. Što se dogodilo?', null, null, 'Діалог «Сусід нас затопив»: «Dobar dan. Što se dogodilo?» (Добрий день. Що сталося?) — «Voda je procurila kroz strop u našoj kupaonici.» (Вода протекла крізь стелю в нашій ванній.).', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f54374e9-fa4e-5abf-bbfb-ba23b3dd2448', v_aid, 10, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hvala. Moram li i ja nešto napraviti zbog posla?', '["Točno. I ne zaboravi potpis.", "Čujemo. Molim sve ostale da isključe mikrofon.", "Da, Vaša liječnica Vam mora zatvoriti bolovanje radi njege djeteta."]'::jsonb, 2, null, '{}'::text[], 'Hvala. Moram li i ja nešto napraviti zbog posla?', null, null, 'Діалог «Довідка для садочка»: «Hvala. Moram li i ja nešto napraviti zbog posla?» (Дякую. Мені теж треба щось зробити через роботу?) — «Da, Vaša liječnica Vam mora zatvoriti bolovanje radi njege djeteta.» (Так, ваша лікарка має закрити вам лікарняний по догляду за дитиною.).', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9f04ab95-d431-56d8-a132-c0fc874067bd', v_aid, 11, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoćete li me ispravljati kad pogriješim?', '["Samo dva kofera. Spakirali smo dokumente, odjeću i fotografije.", "Navikla se. Najvažnija je zdrava prehrana i redoviti pregledi.", "Naravno. A kod kuće samostalno učite riječi i čitajte naglas."]'::jsonb, 2, null, '{}'::text[], 'Hoćete li me ispravljati kad pogriješim?', null, null, 'Діалог «Як я просуваюся?»: «Hoćete li me ispravljati kad pogriješim?» (Ви виправлятимете мене, коли я помилятимуся?) — «Naravno. A kod kuće samostalno učite riječi i čitajte naglas.» (Звісно. А вдома самостійно вчіть слова й читайте вголос.).', (select id from public.lessons where id = '8190831a-549a-544a-962b-4f716a895a32'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2453711d-9315-5ca0-a172-e3b9b1a2fe0b', v_aid, 12, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što ste se igrali?', '["Ja ću ga poslati danas poslije podne.", "Morate, i račun mora biti fiskaliziran.", "Cijele dane smo bili vani: skrivača, lovice, ljuljačka iza kuće."]'::jsonb, 2, null, '{}'::text[], 'Što ste se igrali?', null, null, 'Діалог «Де ти росла?»: «Što ste se igrali?» (У що ви гралися?) — «Cijele dane smo bili vani: skrivača, lovice, ljuljačka iza kuće.» (Цілими днями ми були надворі: хованки, квач, гойдалка за хатою.).', (select id from public.lessons where id = '65e0eec5-f830-5509-a807-db00ace41075'), 'PUBLISHED', 'claude_assessment_v5'),
  ('91a479c9-5191-5e87-af10-3bc02b909580', v_aid, 13, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hvala. Mogu li dobiti i cjenik za sljedeću godinu?', '["Svakako. Poslat ću ga u istom e-mailu.", "Slomila sam je na skijanju prošli mjesec.", "Nitko, sve radi sama. Jednom mjesečno ide na kontrolni pregled."]'::jsonb, 0, null, '{}'::text[], 'Hvala. Mogu li dobiti i cjenik za sljedeću godinu?', null, null, 'Діалог «Немає вкладення»: «Hvala. Mogu li dobiti i cjenik za sljedeću godinu?» (Дякую. Чи можу я отримати й прейскурант на наступний рік?) — «Svakako. Poslat ću ga u istom e-mailu.» (Звісно. Надішлю його в тому самому листі.).', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c1f0df69-2e06-5cf5-85a6-3e23c87543fd', v_aid, 14, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Onda se pomirimo uz kavu?', '["Oko dva mjeseca. Ako ne želite čekati, postoji privatna poliklinika.", "Možemo, ako raspodijelimo zadatke. Ja ću preuzeti izvještaj.", "Može. Važno mi je da smo opet dobro."]'::jsonb, 2, null, '{}'::text[], 'Onda se pomirimo uz kavu?', null, null, 'Діалог «Вибачення»: «Onda se pomirimo uz kavu?» (Тоді помиримося за кавою?) — «Može. Važno mi je da smo opet dobro.» (Можна. Мені важливо, що в нас знову все добре.).', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4069c4ba-0e5b-5746-af0a-1f9bba3fc13d', v_aid, 15, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan! Jeste li naručeni?', '["Jesam, za šišanje u deset. Samo me malo podšišajte.", "Učim ih cijeli tjedan, ali još nisam naučila sve.", "Prodavač je bio neljubazan. To je neprihvatljivo."]'::jsonb, 0, null, '{}'::text[], 'Dobar dan! Jeste li naručeni?', null, null, 'Діалог «У перукарні»: «Dobar dan! Jeste li naručeni?» (Добрий день! Ви записані?) — «Jesam, za šišanje u deset. Samo me malo podšišajte.» (Так, на стрижку о десятій. Просто трохи підрівняйте.).', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ac886321-daa9-5a83-9551-563c59930c37', v_aid, 16, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Na stražnjim vratima je ogrebotina. Možete li to zapisati?', '["Добрий день, у мене бронь на маленьке авто з автоматичною коробкою.", "Звісно. Якщо повернете авто з повним баком, нічого не платите.", "Триста євро, ми заблокуємо їх на картці. Авто з повним баком."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Dobar dan, imam rezervaciju za mali auto s automatskim mjenjačem.
Službenik: Izvolite. Hoćete li kasko osiguranje? Bez njega je franšiza tisuću eura.
Daša: Hoću. A kolika je kaucija?
Službenik: Tristo eura, blokirat ćemo ih na kartici. Auto je s punim spremnikom.
Daša: Na stražnjim vratima je ogrebotina. Možete li to zapisati?
Službenik: Naravno. Ako vratite auto s punim spremnikom, ništa ne plaćate.', 'Daša: Добрий день, у мене бронь на маленьке авто з автоматичною коробкою.
Službenik: Прошу. Бажаєте страхування каско? Без нього франшиза тисяча євро.
Daša: Так. А яка застава?
Službenik: Триста євро, ми заблокуємо їх на картці. Авто з повним баком.
Daša: На задніх дверях подряпина. Можете це записати?
Službenik: Звісно. Якщо повернете авто з повним баком, нічого не платите.', 'Діалог «У прокаті»: «Na stražnjim vratima je ogrebotina. Možete li to zapisati?» — «Naravno. Ako vratite auto s punim spremnikom, ništa ne plaćate.», тобто «Звісно. Якщо повернете авто з повним баком, нічого не платите.».', (select id from public.lessons where id = '35e0e7d1-e7a5-5633-8656-21231dc30640'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4a111ef0-5789-5434-8cfc-8ac96497cb08', v_aid, 17, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kada ću dobiti odgovor?', '["У визначений законом строк, до тридцяти днів. Рішення надсилають поштою.", "Ви маєте право на оскарження протягом п’ятнадцяти днів.", "Тут, у канцелярії. Ось ваш вхідний номер."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Dobar dan, gdje se predaje zahtjev za vrtić?
Službenica: Ovdje, u pisarnici. Ovo je Vaš urudžbeni broj.
Daša: Kada ću dobiti odgovor?
Službenica: U zakonskom roku, do trideset dana. Rješenje se šalje poštom.
Daša: A ako zahtjev bude odbijen?
Službenica: Imate pravo na žalbu u roku od petnaest dana.', 'Daša: Добрий день, де подають заяву до садочка?
Službenica: Тут, у канцелярії. Ось ваш вхідний номер.
Daša: Коли я отримаю відповідь?
Službenica: У визначений законом строк, до тридцяти днів. Рішення надсилають поштою.
Daša: А якщо заяву відхилять?
Službenica: Ви маєте право на оскарження протягом п’ятнадцяти днів.', 'Діалог «У канцелярії»: «Kada ću dobiti odgovor?» — «U zakonskom roku, do trideset dana. Rješenje se šalje poštom.», тобто «У визначений законом строк, до тридцяти днів. Рішення надсилають поштою.».', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0f8f0eb0-cc26-5228-91ca-8e2676f73579', v_aid, 18, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Darja, kako su izgledali prvi mjeseci u Hrvatskoj?', '["Спочатку так. Але щойно я записалася на курс, познайомилася з людьми.", "Важкими. Я не знала, як дати собі раду, а ще сумувала за мамою.", "Тепер я звикла. Я пишаюся всім, чого ми досягли."]'::jsonb, 1, null, '{}'::text[], null, 'Ivana: Darja, kako su izgledali prvi mjeseci u Hrvatskoj?
Darja: Teški. Nisam se znala snaći, a nedostajala mi je mama.
Ivana: Jesi li se osjećala usamljeno?
Darja: Na početku jesam. Ali čim sam upisala tečaj, upoznala sam ljude.
Ivana: A sad?
Darja: Sad sam se priviknula. Ponosna sam na sve što smo postigli.', 'Ivana: Дар’є, якими були перші місяці в Хорватії?
Darja: Важкими. Я не знала, як дати собі раду, а ще сумувала за мамою.
Ivana: Ти почувалася самотньою?
Darja: Спочатку так. Але щойно я записалася на курс, познайомилася з людьми.
Ivana: А тепер?
Darja: Тепер я звикла. Я пишаюся всім, чого ми досягли.', 'Діалог «Перші місяці»: «Darja, kako su izgledali prvi mjeseci u Hrvatskoj?» — «Teški. Nisam se znala snaći, a nedostajala mi je mama.», тобто «Важкими. Я не знала, як дати собі раду, а ще сумувала за мамою.».', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_v5'),
  ('93feb9e1-8b3b-531c-b6c6-ac0a75efa311', v_aid, 19, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ivan je tada na godišnjem. Poklapa li se to?', '["Чудово, так усе вирішено.", "Даша. Я передам їй справи й увімкну автовідповідь.", "Частково. Я могла б почати на тиждень пізніше."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Šefice, bih li mogla uzeti godišnji od petog do dvadesetog kolovoza?
Šefica: Ivan je tada na godišnjem. Poklapa li se to?
Darja: Djelomično. Mogla bih krenuti tjedan kasnije.
Šefica: Dobro, odobrit ću zahtjev. Tko će ti biti zamjenik?
Darja: Daša. Napravit ću s njom primopredaju i uključiti automatski odgovor.
Šefica: Odlično, tako je sve riješeno.', 'Darja: Пані керівнице, чи могла б я взяти відпустку з п’ятого до двадцятого серпня?
Šefica: Іван тоді у відпустці. Це збігається?
Darja: Частково. Я могла б почати на тиждень пізніше.
Šefica: Добре, я погоджу заяву. Хто тебе заступатиме?
Darja: Даша. Я передам їй справи й увімкну автовідповідь.
Šefica: Чудово, так усе вирішено.', 'Діалог «Прошу відпустку»: «Ivan je tada na godišnjem. Poklapa li se to?» — «Djelomično. Mogla bih krenuti tjedan kasnije.», тобто «Частково. Я могла б почати на тиждень пізніше.».', (select id from public.lessons where id = '0e0d07a2-2a6c-5090-ab84-3089f20a48b8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('344e1fe1-d9b9-50ff-833a-ea46d73c5ee5', v_aid, 20, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Сядьмо в тінь». Що ви скажете?', null, '["Sjednimo u hlad.", "Možete li nas premjestiti u drugu sobu?", "Htio bih ulaznicu za jedanaest."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Сядьмо в тінь.» — «Sjednimo u hlad.».', (select id from public.lessons where id = 'bd9353b6-9d9e-5192-8124-f6a2dcf3f178'), 'PUBLISHED', 'claude_assessment_v5'),
  ('830fe83f-1422-573d-9f4e-67ff47704d43', v_aid, 21, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хочу поговорити з керівником». Що ви скажете?', null, '["Po karakteru nalikuje ocu.", "Želim razgovarati s voditeljem.", "Tvoj zahtjev je potpuno opravdan."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я хочу поговорити з керівником.» — «Želim razgovarati s voditeljem.».', (select id from public.lessons where id = '2760a712-4fa2-56fd-b036-8427682ad804'), 'PUBLISHED', 'claude_assessment_v5'),
  ('66f3a325-08b6-5774-8924-1a72bb3bd516', v_aid, 22, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «У мене підвищений тиск». Що ви скажете?', null, '["Imam povišen tlak.", "Trebam uputnicu za kardiologa.", "Prehladio sam se na kiši."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«У мене підвищений тиск.» — «Imam povišen tlak.».', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_v5'),
  ('89c5843f-5191-5888-a452-4635a9b6e0de', v_aid, 23, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «певною мірою»', null, '[]'::jsonb, null, 'donekle', '{}'::text[], null, null, null, '«певною мірою» — donekle.', (select id from public.lessons where id = 'f029711f-710e-5327-be4d-2310435e6eac'), 'PUBLISHED', 'claude_assessment_v5'),
  ('eed1a19e-72f0-5ddb-8bdd-a1666a398002', v_aid, 24, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «інший номер»', null, '[]'::jsonb, null, 'druga soba', '{}'::text[], null, null, null, '«інший номер» — druga soba.', (select id from public.lessons where id = '778e1a8f-01d6-5bc0-b3e3-3e3123551c8b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('74e0215e-1e57-52e9-947b-5e229beae63c', v_aid, 25, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «електронне направлення»', null, '[]'::jsonb, null, 'e-uputnica', '{}'::text[], null, null, null, '«електронне направлення» — e-uputnica.', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6021e4a8-d49e-580d-937b-ec322e55d073', v_aid, 26, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Кінцевий строк — п’ятниця опівдні.»', null, '["petak", "je", "u", "podne.", "Krajnji", "rok"]'::jsonb, null, 'Krajnji rok je petak u podne.', array['Petak u podne je krajnji rok.']::text[], null, null, null, '«Кінцевий строк — п’ятниця опівдні.» — «Krajnji rok je petak u podne.».', (select id from public.lessons where id = '97f1ba90-fe04-5907-803f-2ec0854b0a09'), 'PUBLISHED', 'claude_assessment_v5'),
