-- Фінальна перевірка рівня A2 · 48 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-final' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-final — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '3f38d710-a564-53e7-ad05-b37f86ee98ab') then return; end if;  -- уже оновлено
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Кінець рівня (усі 14 модулів A2): 48 завдань на 4 навички. ~25 хв.', estimated_minutes = 25 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('3f38d710-a564-53e7-ad05-b37f86ee98ab', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Супер, дякую! Запишу все.", "Бурий ведмідь узимку спить. Не хвилюйся!", "Гарно. Темп життя повільніший, ніж у Загребі."]'::jsonb, 0, null, '{}'::text[], 'Super, hvala! Zapisat ću sve.', null, null, 'Прозвучало: «Super, hvala! Zapisat ću sve.» — «Супер, дякую! Запишу все.».', (select id from public.lessons where id = 'df44c302-d9be-51e9-9c3f-a5faf4ca04a6'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9941b472-eb52-51ec-8a16-b3ba92d4d602', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Тоді тобі треба повідомити поліцію?", "А вартість життя?", "А що тобі не подобається?"]'::jsonb, 2, null, '{}'::text[], 'A što ti se ne sviđa?', null, null, 'Прозвучало: «A što ti se ne sviđa?» — «А що тобі не подобається?».', (select id from public.lessons where id = '0465a2cd-1da9-5a6e-a47d-434fc8bee342'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6b4b9185-6006-5ca6-8890-fd3e560fdc22', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Літо дедалі спекотніше. Зміна клімату справді відчувається.", "Улітку раз на тиждень, а взимку майже ніколи.", "Добра ідея, візьму з собою й дітей."]'::jsonb, 1, null, '{}'::text[], 'Ljeti jednom tjedno, a zimi gotovo nikad.', null, null, 'Прозвучало: «Ljeti jednom tjedno, a zimi gotovo nikad.» — «Улітку раз на тиждень, а взимку майже ніколи.».', (select id from public.lessons where id = '47da19c6-e1f7-589a-87a2-e78e419c206a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('238ee620-1059-5730-bfdf-6c4bef1a33f7', v_aid, 4, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добрий день, я хотів би продовжити термін позики.", "Твоя правда. Подивлюся сьогодні ввечері новини.", "Тільки не розповідай мені фінал! Ідемо в п’ятницю."]'::jsonb, 2, null, '{}'::text[], 'Samo mi nemoj otkriti kraj! Idemo u petak.', null, null, 'Прозвучало: «Samo mi nemoj otkriti kraj! Idemo u petak.» — «Тільки не розповідай мені фінал! Ідемо в п’ятницю.».', (select id from public.lessons where id = 'ef11286d-512d-524a-9edc-e760010d1037'), 'PUBLISHED', 'claude_assessment_v5'),
  ('48f2fe46-1919-506c-9ad7-b7ca88ff9d73', v_aid, 5, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Перепрошую вас. Я поговорю з ним.", "А зараз? Усі біжать до нареченої.", "Дорогі гості, піднімімо келихи за молодят! Будьмо!"]'::jsonb, 1, null, '{}'::text[], 'A sad? Svi trče prema mladenki.', null, null, 'Прозвучало: «A sad? Svi trče prema mladenki.» — «А зараз? Усі біжать до нареченої.».', (select id from public.lessons where id = '68f2ada8-2352-5450-a073-72754ae0feb8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f00f162d-3320-59ef-bae2-84855507d37a', v_aid, 6, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дуже боліло?", "Який тиск цього місяця?", "Чи будуть наслідки?"]'::jsonb, 0, null, '{}'::text[], 'Je li jako boljelo?', null, null, 'Прозвучало: «Je li jako boljelo?» — «Дуже боліло?».', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_v5'),
  ('72dd67d4-50fe-5419-bb04-d8820c0ecabb', v_aid, 7, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Трохи, нічого страшного.", "Добре, але їдь обережно, дорога вузька.", "Тоді заплачу одразу. Надалі їздитиму уважніше."]'::jsonb, 0, null, '{}'::text[], 'Malo, to nije ništa strašno.', null, null, 'Прозвучало: «Malo, to nije ništa strašno.» — «Трохи, нічого страшного.».', (select id from public.lessons where id = '6a010148-5c1c-5e64-ab4a-c030b3adb969'), 'PUBLISHED', 'claude_assessment_v5'),
  ('37a82559-480c-5f94-958b-3a7610339025', v_aid, 8, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Звучить чудово. Що порадите з напоїв?", "Що таке клапа?", "Супер. А на пам’ять?"]'::jsonb, 0, null, '{}'::text[], 'Zvuči odlično. Što preporučujete za piće?', null, null, 'Прозвучало: «Zvuči odlično. Što preporučujete za piće?» — «Звучить чудово. Що порадите з напоїв?».', (select id from public.lessons where id = 'df44c302-d9be-51e9-9c3f-a5faf4ca04a6'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b231bc05-8af9-53ff-ba01-65adaa355da3', v_aid, 9, 'A2', 'reading', 'understand', 'multiple_choice', 'Де вона працює зараз?', 'Kako sam našla posao', '["На рецепції готелю", "У школі", "У ресторані"]'::jsonb, 0, null, '{}'::text[], null, 'Kad sam došla u Hrvatsku, nisam znala ni riječ hrvatskog. Prva tri mjeseca bila su teška. Svaki dan sam učila nove riječi i gledala hrvatske serije s titlovima. Onda sam počela tražiti posao. Poslala sam životopis u deset hotela, ali nitko mi nije odgovorio. Jednog dana nazvala me voditeljica jednog malog hotela u Splitu i pozvala me na razgovor. Bila sam jako nervozna, ali sve je prošlo dobro. Razgovarale smo pola na hrvatskom, pola na engleskom. Sljedeći tjedan počela sam raditi na recepciji. Danas tamo radim već dvije godine i hrvatski mi više nije problem.', 'Коли я приїхала до Хорватії, я не знала жодного слова хорватською. Перші три місяці були важкими. Щодня я вчила нові слова й дивилася хорватські серіали із субтитрами. Потім я почала шукати роботу. Я надіслала резюме в десять готелів, але ніхто мені не відповів. Одного дня мені зателефонувала керівниця одного маленького готелю в Спліті й запросила мене на співбесіду. Я дуже хвилювалася, але все пройшло добре. Ми розмовляли наполовину хорватською, наполовину англійською. Наступного тижня я почала працювати на рецепції. Сьогодні я працюю там уже два роки, і хорватська для мене більше не проблема.', 'Текст «Як я знайшла роботу». Правильна відповідь: «На рецепції готелю».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('f51d87c0-8945-52a2-adbb-72e4709a9a4f', v_aid, 10, 'A2', 'reading', 'understand', 'multiple_choice', 'Що сталося у ванній?', 'Problem u stanu', '["Розбилося дзеркало", "Під умивальником тече вода", "Не працює світло"]'::jsonb, 1, null, '{}'::text[], null, 'Poštovani gospodine Horvat,
pišem Vam jer već tri dana u kupaonici curi voda ispod umivaonika. Zatvorila sam slavinu, ali voda opet kapa, a odvod je začepljen. Na podu je stalno voda i strah me je da će proći do susjeda ispod nas. Također, perilica rublja se pokvarila prošle subote, a u spremištu u podrumu ima puno vlage i plijesni. Molim Vas da što prije pošaljete vodoinstalatera. Kod kuće sam svaki dan poslije 16 sati, a u subotu cijeli dan. Ako je kvar hitan, nazvat ću hitnu intervenciju, a račun ću Vam poslati.
Unaprijed hvala.
Lijep pozdrav,
Olena Kovalenko', 'Шановний пане Хорвате!
Пишу вам, бо вже три дні у ванній тече вода під умивальником. Я закрила кран, але вода знову капає, а злив засмічений. На підлозі постійно вода, і я боюся, що вона протече до сусідів під нами. Також минулої суботи зламалася пральна машина, а в коморі в підвалі багато вогкості й плісняви. Прошу вас якнайшвидше надіслати сантехніка. Я вдома щодня після 16-ї години, а в суботу — цілий день. Якщо поломка термінова, я викличу аварійну службу, а рахунок надішлю вам.
Заздалегідь дякую.
З найкращими побажаннями,
Олена Коваленко', 'Текст «Проблема в квартирі». Правильна відповідь: «Під умивальником тече вода».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('fc047d69-30ee-5c88-92c6-016ea78b0e89', v_aid, 11, 'A2', 'reading', 'understand', 'multiple_choice', 'Чого бракує на вікні?', 'Prigovor na apartman', '["Сітки від комарів", "Ручки", "Штор"]'::jsonb, 0, null, '{}'::text[], null, 'Poštovani gospodine Babiću,
jučer smo stigli u vaš apartman u Makarskoj. Lokacija je odlična i plaža je blizu, ali imamo nekoliko problema. Klima-uređaj ne funkcionira, a u kupaonici curi voda iz tuš kabine. Također, na prozoru nema mrežice protiv komaraca, pa noću ne možemo spavati. U oglasu je pisalo da je doručak uključen, ali danas ujutro nitko nije došao. Molim vas da riješite problem što prije ili da nas premjestite u drugi apartman. Ako to nije moguće, htjeli bismo dobiti povrat predujma.
Unaprijed hvala,
Darja Kovalenko', 'Шановний пане Бабичу!
Учора ми приїхали до ваших апартаментів у Макарській. Розташування чудове, і пляж поруч, але в нас є кілька проблем. Кондиціонер не працює, а у ванній з душової кабіни тече вода. Також на вікні немає сітки від комарів, тож уночі ми не можемо спати. В оголошенні було написано, що сніданок включено, але сьогодні вранці ніхто не прийшов. Прошу вас якнайшвидше розв''язати проблему або переселити нас в інші апартаменти. Якщо це неможливо, ми хотіли б отримати назад передоплату.
Заздалегідь дякую,
Дар''я Коваленко', 'Текст «Скарга на апартаменти». Правильна відповідь: «Сітки від комарів».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('7684214b-9525-543d-9bb1-40b7b95c64dc', v_aid, 12, 'A2', 'reading', 'understand', 'multiple_choice', 'Що пишуть усі перед записом?', 'Tečajevi hrvatskog jezika za odrasle', '["Заяву", "Безкоштовний тест рівня", "Твір"]'::jsonb, 1, null, '{}'::text[], null, 'TEČAJEVI HRVATSKOG JEZIKA ZA ODRASLE
Pučko otvoreno učilište poziva polaznike na upis u zimski semestar.
Nudimo:
– početni tečaj za početnike – dva puta tjedno, večernji tečaj od 18 do 20 sati;
– napredni tečaj – ponedjeljkom i srijedom;
– individualnu nastavu po dogovoru.
Radimo u malim grupama, najviše deset polaznika. Prije upisa svi polaznici pišu besplatan test razine. Školarina je 300 eura po tečaju, a moguće je i plaćanje u ratama. Na kraju tečaja dobivate potvrdu o pohađanju, a možete polagati i ispit iz hrvatskog.
Upisi traju do 15. siječnja.', 'КУРСИ ХОРВАТСЬКОЇ МОВИ ДЛЯ ДОРОСЛИХ
Народний відкритий університет запрошує слухачів записатися на зимовий семестр.
Пропонуємо:
– початковий курс для початківців – двічі на тиждень, вечірній курс із 18 до 20 години;
– курс для просунутих – по понеділках і середах;
– індивідуальні заняття за домовленістю.
Працюємо в малих групах, щонайбільше десять слухачів. Перед записом усі слухачі пишуть безкоштовний тест рівня. Вартість навчання – 300 євро за курс, можна платити й частинами. Наприкінці курсу ви отримуєте довідку про відвідування, а також можете скласти іспит з хорватської.
Запис триває до 15 січня.', 'Текст «Курси хорватської для дорослих». Правильна відповідь: «Безкоштовний тест рівня».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('96c92a9d-0350-52a5-ba40-8fe0ca20e9dd', v_aid, 13, 'A2', 'reading', 'understand', 'multiple_choice', 'Що вона відчуває тепер?', 'Pismo prijateljici', '["Страх", "Сум", "Більше впевненості в собі"]'::jsonb, 2, null, '{}'::text[], null, 'Draga Oksana,
hvala ti na pismu, jako mi nedostaješ! Imam puno novosti. Ukratko: napokon sam položila ispit iz hrvatskog! Sada se puno bolje snalazim u svakodnevnim situacijama. Prošli tjedan sam bila kod liječnika i sama sam opisala simptome, bez prevoditelja. Na poslu sam se samostalno dogovorila sa šefom oko godišnjeg odmora. Prije dvije godine to nisam mogla ni zamisliti. Naravno, još uvijek griješim, ali učim iz pogrešaka. Imam više samopouzdanja i osjećam da je ovo novo poglavlje u mom životu. Kad dolaziš u posjet? Jedva čekam da te vidim!
Piši mi i pozdravi svoje!
Tvoja Darja', 'Дорога Оксано!
Дякую тобі за листа, я дуже за тобою сумую! У мене багато новин. Коротко: нарешті я склала іспит з хорватської! Тепер я набагато краще даю собі раду в щоденних ситуаціях. Минулого тижня я була в лікаря й сама описала симптоми, без перекладача. На роботі я самостійно домовилася з шефом про відпустку. Два роки тому я не могла навіть уявити цього. Звісно, я ще помиляюся, але вчуся на помилках. Я стала впевненішою в собі й відчуваю, що це новий розділ у моєму житті. Коли ти приїдеш у гості? Не можу дочекатися, щоб тебе побачити!
Пиши мені й передавай вітання своїм!
Твоя Дар''я', 'Текст «Лист подрузі: я даю собі раду». Правильна відповідь: «Більше впевненості в собі».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('e4d06bef-1932-5e0b-8a2c-755b5a0ea376', v_aid, 14, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan, trebam potvrdu za vrtić. Kome se mogu obratiti?', '["Raspremit ćemo zajedno, brzo će ići.", "Meni. Trebam rodni list i Vašu iskaznicu.", "Jako. Nedostaju mi prijatelji i naš kruh."]'::jsonb, 1, null, '{}'::text[], 'Dobar dan, trebam potvrdu za vrtić. Kome se mogu obratiti?', null, null, 'Діалог «В установі»: «Dobar dan, trebam potvrdu za vrtić. Kome se mogu obratiti?» (Добрий день, мені потрібна довідка для садочка. До кого я можу звернутися?) — «Meni. Trebam rodni list i Vašu iskaznicu.» (До мене. Мені потрібне свідоцтво про народження й ваша посвідка.).', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('07b60195-a9d9-552e-b909-871c8aa0fe56', v_aid, 15, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako je tlak ovaj mjesec?', '["Običaj je donijeti vino ili cvijeće. I ne kasnite.", "Kad se sve zbroji, jest.", "Ujutro je viši, navečer je niži. Vodim dnevnik tlaka."]'::jsonb, 2, null, '{}'::text[], 'Kako je tlak ovaj mjesec?', null, null, 'Діалог «Мій тиск»: «Kako je tlak ovaj mjesec?» (Який тиск цього місяця?) — «Ujutro je viši, navečer je niži. Vodim dnevnik tlaka.» (Уранці вищий, увечері нижчий. Я веду щоденник тиску.).', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_v5'),
  ('70b6fcd2-8eb5-5016-9280-f11d9b2291fe', v_aid, 16, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što vam je dugoročni plan?', '["S hrvatskim titlovima. Kino projekcija je u dvadeset i trideset.", "Dvadeset prvog travnja tisuću devetsto devedesete.", "Kupiti stan. Štedimo svaki mjesec po malo."]'::jsonb, 2, null, '{}'::text[], 'Što vam je dugoročni plan?', null, null, 'Діалог «Довгий план»: «Što vam je dugoročni plan?» (Який у вас довгостроковий план?) — «Kupiti stan. Štedimo svaki mjesec po malo.» (Купити квартиру. Відкладаємо щомісяця потроху.).', (select id from public.lessons where id = 'f2760130-fd69-5932-978c-cc424aaefafa'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fcc5fb72-2327-57ef-8081-9bc9ec58d448', v_aid, 17, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Razumijem. Imam dvoje djece. Mogu li imati veći osobni odbitak?', '["Možete. Donesite nam njihove podatke i promijenit ćemo poreznu karticu.", "Zahtjev moram dopuniti u roku od osam dana.", "Kod kuće ukrajinski, vani hrvatski. To je naše pravilo."]'::jsonb, 0, null, '{}'::text[], 'Razumijem. Imam dvoje djece. Mogu li imati veći osobni odbitak?', null, null, 'Діалог «Розрахунковий лист»: «Razumijem. Imam dvoje djece. Mogu li imati veći osobni odbitak?» (Зрозуміло. У мене двоє дітей. Чи можу я мати більшу неоподатковувану суму?) — «Možete. Donesite nam njihove podatke i promijenit ćemo poreznu karticu.» (Можете. Принесіть нам їхні дані, і ми змінимо податкову картку.).', (select id from public.lessons where id = 'b9bcea21-08a3-56cf-be72-edf6b6c7b03f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b02639dd-9c88-51a1-9500-01a395d19a0c', v_aid, 18, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Daša, jesi li pročitala uvjete otkazivanja?', '["Svatko donosi nešto. Troškove za torte ćemo podijeliti.", "Jesam. Besplatno otkazivanje je do mjesec dana prije dolaska.", "„Molila bih Vas…“ ili „Bila bih Vam zahvalna…“"]'::jsonb, 1, null, '{}'::text[], 'Daša, jesi li pročitala uvjete otkazivanja?', null, null, 'Діалог «Умови скасування»: «Daša, jesi li pročitala uvjete otkazivanja?» (Дашо, ти прочитала умови скасування?) — «Jesam. Besplatno otkazivanje je do mjesec dana prije dolaska.» (Так. Безкоштовне скасування — до місяця перед приїздом.).', (select id from public.lessons where id = '2aaf70f9-5a0c-53a3-a621-e42cc4548661'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ab2f4718-d83f-5f9d-b450-d898aba3dc51', v_aid, 19, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imam dobre bilješke s vježbi. Hoćeš li ih?', '["Hoću, hvala! Bez njih ne bih znala ponoviti gradivo.", "Obično do mjesec dana nakon procjene.", "Lijepo. Tempo života je sporiji nego u Zagrebu."]'::jsonb, 0, null, '{}'::text[], 'Imam dobre bilješke s vježbi. Hoćeš li ih?', null, null, 'Діалог «Перед іспитом»: «Imam dobre bilješke s vježbi. Hoćeš li ih?» (У мене гарний конспект із практичних. Хочеш?) — «Hoću, hvala! Bez njih ne bih znala ponoviti gradivo.» (Хочу, дякую! Без нього я б не знала, як повторити матеріал.).', (select id from public.lessons where id = '4be96321-cd99-57ff-a9bc-17cfaf4f4c29'), 'PUBLISHED', 'claude_assessment_v5'),
  ('621e5a11-cb7f-57ff-b485-32af44bfab8b', v_aid, 20, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dašo, gdje bacamo ostatke hrane?', '["Našu malvaziju ili teran. Vino je iz našeg vinograda.", "U smeđu kantu za biootpad. Ali ne u plastičnoj vrećici!", "Slično, ali manje. Klapsko pjevanje je na popisu UNESCO-a."]'::jsonb, 1, null, '{}'::text[], 'Dašo, gdje bacamo ostatke hrane?', null, null, 'Діалог «Біовідходи»: «Dašo, gdje bacamo ostatke hrane?» (Дашо, куди викидаємо залишки їжі?) — «U smeđu kantu za biootpad. Ali ne u plastičnoj vrećici!» (У коричневий бак для біовідходів. Але не в пластиковому пакеті!).', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5c666c5e-a7d2-58d2-a456-4916ea877e16', v_aid, 21, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imate li osiguranje kućanstva?', '["Imamo, broj police je u e-mailu.", "Teško. Uzmi barem mali komad, to je pristojno.", "Dan neovisnosti Ukrajine. Kulturno društvo organizira koncert."]'::jsonb, 0, null, '{}'::text[], 'Imate li osiguranje kućanstva?', null, null, 'Діалог «Затоплення»: «Imate li osiguranje kućanstva?» (У вас є страхування домашнього майна?) — «Imamo, broj police je u e-mailu.» (Є, номер поліса в листі.).', (select id from public.lessons where id = 'f3cfca9e-efc9-5b58-8fe9-772fa631e0c2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6e5d5c94-d308-530e-8122-8f29c825cefe', v_aid, 22, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li skijališta?', '["Samo dobro raspoloženje. Poslije koncerta je druženje uz domaću hranu.", "Ima, malo skijalište u Platku. A djeca se mogu sanjkati.", "Boravak u prirodi. Vikendom idem na Sljeme i isključim mobitel."]'::jsonb, 1, null, '{}'::text[], 'Ima li skijališta?', null, null, 'Діалог «Зима в Горському Котарі»: «Ima li skijališta?» (Є лижні схили?) — «Ima, malo skijalište u Platku. A djeca se mogu sanjkati.» (Є, невеликий схил у Платаку. А діти можуть кататися на санчатах.).', (select id from public.lessons where id = 'ab060253-8099-5e7d-bfaa-1b1a7655c229'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b3342c0a-ff5a-5132-b55a-1e3b24fefbd8', v_aid, 23, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Nema problema. Može idući ponedjeljak u devet?', '["Fiš paprikaš je kao naša juha, samo ljući!", "Za tri tjedna. Do tada vozite s privremenom potvrdom.", "Može. Javit ću Vam ako se nešto promijeni."]'::jsonb, 2, null, '{}'::text[], 'Nema problema. Može idući ponedjeljak u devet?', null, null, 'Діалог «Скасування в лікаря»: «Nema problema. Može idući ponedjeljak u devet?» (Без проблем. Можна наступного понеділка о дев’ятій?) — «Može. Javit ću Vam ako se nešto promijeni.» (Можна. Я вам повідомлю, якщо щось зміниться.).', (select id from public.lessons where id = '0b054356-d4b4-5f6e-b7e9-3dc8f3c9d4ff'), 'PUBLISHED', 'claude_assessment_v5'),
  ('22d16acc-d971-5856-8677-2f54659d37b2', v_aid, 24, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Djeci isto produljujete?', '["Ponekad. Ali purica s mlincima je svima razumljiva!", "Do isteka zaliha. I dostava je besplatna.", "Da, svim članovima obitelji. Nove iskaznice podižete za dva tjedna."]'::jsonb, 2, null, '{}'::text[], 'Djeci isto produljujete?', null, null, 'Діалог «Продовження статусу»: «Djeci isto produljujete?» (Дітям теж продовжуєте?) — «Da, svim članovima obitelji. Nove iskaznice podižete za dva tjedna.» (Так, усім членам родини. Нові посвідки забираєте через два тижні.).', (select id from public.lessons where id = '5e298915-e179-5d58-bca0-6531c7b43a46'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b162e04e-c403-575c-94cc-a039e405bab0', v_aid, 25, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imate li račun i jamstveni list?', '["Тоді напишіть письмову скаргу. Строк відповіді — п’ятнадцять днів.", "Є. Ви продали її мені як нову, а вона не працює.", "Ми віддамо її в сервіс."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Dobar dan. Perilica koju sam kupila se pokvarila nakon mjesec dana.
Prodavač: Imate li račun i jamstveni list?
Darja: Imam. Prodali ste mi je kao novu, a ne radi.
Prodavač: Odnijet ćemo je u servis.
Darja: Ne slažem se. Zahtijevam novu perilicu ili povrat novca.
Prodavač: Onda napišite pisani prigovor. Rok za odgovor je petnaest dana.', 'Darja: Добрий день. Пральна машина, яку я купила, зламалася через місяць.
Prodavač: У вас є чек і гарантійний талон?
Darja: Є. Ви продали її мені як нову, а вона не працює.
Prodavač: Ми віддамо її в сервіс.
Darja: Я не згодна. Вимагаю нову пральну машину або повернення грошей.
Prodavač: Тоді напишіть письмову скаргу. Строк відповіді — п’ятнадцять днів.', 'Діалог «Зламана пральна машина»: «Imate li račun i jamstveni list?» — «Imam. Prodali ste mi je kao novu, a ne radi.», тобто «Є. Ви продали її мені як нову, а вона не працює.».', (select id from public.lessons where id = '2760a712-4fa2-56fd-b036-8427682ad804'), 'PUBLISHED', 'claude_assessment_v5'),
  ('95bc54bd-b8c8-557e-9c4c-ae475ead885c', v_aid, 26, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Razumiješ li kajkavski?', '["У Загор’ї. Відвідали замок Тракошчан і були на термальному курорті.", "Іноді. Але індичку з млинцями всі розуміють!", "Годину. Пагорби, виноградники, а бабусі говорять кайкавською."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Gdje ste bili vikendom?
Marko: U Zagorju. Posjetili smo dvorac Trakošćan i bili na topličkom kupalištu.
Darja: Je li daleko od Zagreba?
Marko: Sat vremena. Brežuljci, vinogradi, a bake govore kajkavski.
Darja: Razumiješ li kajkavski?
Marko: Ponekad. Ali purica s mlincima je svima razumljiva!', 'Darja: Де ви були на вихідних?
Marko: У Загор’ї. Відвідали замок Тракошчан і були на термальному курорті.
Darja: Це далеко від Загреба?
Marko: Годину. Пагорби, виноградники, а бабусі говорять кайкавською.
Darja: Ти розумієш кайкавську?
Marko: Іноді. Але індичку з млинцями всі розуміють!', 'Діалог «Вихідні в Загор’ї»: «Razumiješ li kajkavski?» — «Ponekad. Ali purica s mlincima je svima razumljiva!», тобто «Іноді. Але індичку з млинцями всі розуміють!».', (select id from public.lessons where id = 'a312ce34-22d7-56e3-a38e-106205ee21c0'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d65fe0a2-5038-58d2-a354-c7bce46e5232', v_aid, 27, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Nisam. Gdje si to pročitala?', '["На одному порталі. Було на головній.", "Ти чула новини? Я прочитала, що будують новий міст через Саву.", "Добре, тоді завтра скажи мені, чи це правда."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Jesi li čula vijesti? Pročitala sam da se gradi novi most na Savi.
Darja: Nisam. Gdje si to pročitala?
Daša: Na jednom portalu. Bilo je na naslovnici.
Darja: Provjeri izvor. Danas ima puno lažnih vijesti.
Daša: U pravu si. Pogledat ću večeras Dnevnik.
Darja: Dobro, pa mi sutra javi je li istina.', 'Daša: Ти чула новини? Я прочитала, що будують новий міст через Саву.
Darja: Ні. Де ти це прочитала?
Daša: На одному порталі. Було на головній.
Darja: Перевір джерело. Сьогодні багато фейкових новин.
Daša: Твоя правда. Подивлюся сьогодні ввечері новини.
Darja: Добре, тоді завтра скажи мені, чи це правда.', 'Діалог «Що в новинах?»: «Nisam. Gdje si to pročitala?» — «Na jednom portalu. Bilo je na naslovnici.», тобто «На одному порталі. Було на головній.».', (select id from public.lessons where id = '92bd4e0c-f9df-5edb-a65e-9549fe1ef1b8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('edbad506-e530-5411-9626-25c44d3d3e7a', v_aid, 28, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koliko košta izlazak na teren?', '["Можна готівкою або карткою. Отримаєте рахунок і гарантію на роботи.", "Найкраще замінити замок. Можу приїхати завтра вранці.", "Тридцять євро, а новий замок зі встановленням — близько ста."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Dobar dan, zovem zbog brave na ulaznim vratima. Ključ se teško okreće.
Bravar: Najbolje je zamijeniti bravu. Mogu doći sutra ujutro.
Darja: Koliko košta izlazak na teren?
Bravar: Trideset eura, a nova brava s ugradnjom oko sto.
Darja: Je li moguće plaćanje gotovinom?
Bravar: Može gotovinom ili karticom. Dobit ćete račun i jamstvo na radove.', 'Darja: Добрий день, телефоную щодо замка на вхідних дверях. Ключ важко повертається.
Bravar: Найкраще замінити замок. Можу приїхати завтра вранці.
Darja: Скільки коштує виїзд майстра?
Bravar: Тридцять євро, а новий замок зі встановленням — близько ста.
Darja: Можна оплатити готівкою?
Bravar: Можна готівкою або карткою. Отримаєте рахунок і гарантію на роботи.', 'Діалог «Міняємо замок»: «Koliko košta izlazak na teren?» — «Trideset eura, a nova brava s ugradnjom oko sto.», тобто «Тридцять євро, а новий замок зі встановленням — близько ста.».', (select id from public.lessons where id = 'bf43b6bd-d547-596b-8981-55a4043cf238'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0b0efdfc-ad3b-53c5-b395-1bcff93eed02', v_aid, 29, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Mogu li i ja doći?', '["Звісно! Зустріч відкрита для всіх.", "Лише гарний настрій. Після концерту — зустріч за домашньою їжею.", "День Незалежності України. Культурне товариство організовує концерт."]'::jsonb, 0, null, '{}'::text[], null, 'Ivan: Što obilježavate dvadeset četvrtog kolovoza?
Darja: Dan neovisnosti Ukrajine. Kulturno društvo organizira koncert.
Ivan: Mogu li i ja doći?
Darja: Naravno! Druženje je otvoreno svima.
Ivan: Super, dovest ću i suprugu. Trebamo li nešto ponijeti?
Darja: Samo dobro raspoloženje. Poslije koncerta je druženje uz domaću hranu.', 'Ivan: Що ви відзначаєте двадцять четвертого серпня?
Darja: День Незалежності України. Культурне товариство організовує концерт.
Ivan: Можна й мені прийти?
Darja: Звісно! Зустріч відкрита для всіх.
Ivan: Супер, приведу й дружину. Нам щось принести?
Darja: Лише гарний настрій. Після концерту — зустріч за домашньою їжею.', 'Діалог «День Незалежності»: «Mogu li i ja doći?» — «Naravno! Druženje je otvoreno svima.», тобто «Звісно! Зустріч відкрита для всіх.».', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0169db9a-e0a4-5c57-b62a-cc2046dc6988', v_aid, 30, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Dobar dan, imam ukrajinsku vozačku dozvolu. Kako se radi zamjena?', '["Не мусите. Фото на документи роблять тут.", "Вам потрібна медична довідка з медицини праці, паспорт і старе посвідчення.", "Через три тижні. До того їздите з тимчасовою довідкою."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Dobar dan, imam ukrajinsku vozačku dozvolu. Kako se radi zamjena?
Službenik: Trebate liječničko uvjerenje iz medicine rada, putovnicu i staru dozvolu.
Darja: Moram li polagati vozački ispit?
Službenik: Ne morate. Fotografija za dokumente se radi ovdje.
Darja: Kada mogu podići novu dozvolu?
Službenik: Za tri tjedna. Do tada vozite s privremenom potvrdom.', 'Darja: Добрий день, у мене українське посвідчення водія. Як відбувається обмін?
Službenik: Вам потрібна медична довідка з медицини праці, паспорт і старе посвідчення.
Darja: Чи мушу я складати іспит?
Službenik: Не мусите. Фото на документи роблять тут.
Darja: Коли я можу забрати нове посвідчення?
Službenik: Через три тижні. До того їздите з тимчасовою довідкою.', 'Діалог «Обмін водійського посвідчення»: «Dobar dan, imam ukrajinsku vozačku dozvolu. Kako se radi zamjena?» — «Trebate liječničko uvjerenje iz medicine rada, putovnicu i staru dozvolu.», тобто «Вам потрібна медична довідка з медицини праці, паспорт і старе посвідчення.».', (select id from public.lessons where id = 'd4af6240-036d-5046-9c4a-430b34a04c79'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c6b2144a-f570-54dc-b406-af3d62ed13b8', v_aid, 31, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Можете передати їй повідомлення?». Що ви скажете?', null, '["Možemo li pomaknuti rok?", "Htjela bih iskoristiti godišnji u kolovozu.", "Možete li joj prenijeti poruku?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Можете передати їй повідомлення?» — «Možete li joj prenijeti poruku?».', (select id from public.lessons where id = 'd7b6bad3-d46a-5f73-b796-dca7b1538853'), 'PUBLISHED', 'claude_assessment_v5'),
  ('64f981a1-452e-5940-b475-ec939c5d92ee', v_aid, 32, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Можу я заплатити на місці?». Що ви скажете?', null, '["Ispunimo europsko izvješće.", "Nisam vidio znak.", "Mogu li platiti na licu mjesta?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Можу я заплатити на місці?» — «Mogu li platiti na licu mjesta?».', (select id from public.lessons where id = 'dfa42285-bd22-5df8-bf4a-670f56911803'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b613bcef-5f61-5ace-bb09-05f3defaeee5', v_aid, 33, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Сумніваюся, що ціни впадуть». Що ви скажете?', null, '["Prodaje se bicikl, kao nov.", "Sumnjam da će cijene pasti.", "O čemu je ovaj film?"]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Сумніваюся, що ціни впадуть.» — «Sumnjam da će cijene pasti.».', (select id from public.lessons where id = 'd6b9db92-a933-5d45-8f17-f6e911a97ab1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6499b464-4d0e-5558-8f10-a5616d4cf04b', v_aid, 34, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Заспокойся, поговорімо нормально». Що ви скажете?', null, '["Živjeli! Za mladence!", "Smiri se, razgovarajmo normalno.", "Oprosti mi, molim te."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Заспокойся, поговорімо нормально.» — «Smiri se, razgovarajmo normalno.».', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_v5'),
  ('25bc6821-53e0-550b-b025-1f045a0332dd', v_aid, 35, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Скільки чекати на огляд?». Що ви скажете?', null, '["Vrti mi se.", "Stalno sam pod stresom.", "Koliko se čeka na pregled?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Скільки чекати на огляд?» — «Koliko se čeka na pregled?».', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('54f0dc25-7ee9-56a8-aa83-6646821fdd20', v_aid, 36, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «заступник (на час відсутності)»', null, '[]'::jsonb, null, 'zamjenik', '{}'::text[], null, null, null, '«заступник (на час відсутності)» — zamjenik.', (select id from public.lessons where id = '0e0d07a2-2a6c-5090-ab84-3089f20a48b8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('57993a20-6cbb-5a3e-81f2-d936339684be', v_aid, 37, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «вм’ятий»', null, '[]'::jsonb, null, 'udubljen', '{}'::text[], null, null, null, '«вм’ятий» — udubljen.', (select id from public.lessons where id = '306ddbde-6662-5d7e-8c58-eb2c2a17a504'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a98b3719-65e9-5ddf-87a8-20a8dc613c58', v_aid, 38, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «невролог»', null, '[]'::jsonb, null, 'neurolog', '{}'::text[], null, null, null, '«невролог» — neurolog.', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6545bf67-cdca-57e5-92d0-d304b6b95b07', v_aid, 39, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «пообіцяти»', null, '[]'::jsonb, null, 'obećati', '{}'::text[], null, null, null, '«пообіцяти» — obećati.', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d43f2f39-43a2-5d23-8713-7d9bc48e3c0e', v_aid, 40, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «вправлятися, тренувати»', null, '[]'::jsonb, null, 'vježbati', '{}'::text[], null, null, null, '«вправлятися, тренувати» — vježbati.', (select id from public.lessons where id = '8190831a-549a-544a-962b-4f716a895a32'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b880a829-9c0f-5473-80c1-89279f74f420', v_aid, 41, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Наразі я працюю в садочку.»', null, '["radim", "Trenutačno", "vrtiću.", "u"]'::jsonb, null, 'Trenutačno radim u vrtiću.', array['U vrtiću trenutačno radim.', 'Radim trenutačno u vrtiću.']::text[], null, null, null, '«Наразі я працюю в садочку.» — «Trenutačno radim u vrtiću.».', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ea589f26-4d8e-5753-adab-917d83713930', v_aid, 42, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Терміново продам авто.»', null, '["Hitno", "auto.", "prodajem"]'::jsonb, null, 'Hitno prodajem auto.', '{}'::text[], null, null, null, '«Терміново продам авто.» — «Hitno prodajem auto.».', (select id from public.lessons where id = '3fc81316-dca8-5661-88c1-eaf2b61aec07'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9fd0619f-d17b-5564-8566-d77193a4bad9', v_aid, 43, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Годувати тварин заборонено.»', null, '["Zabranjeno", "hraniti", "životinje.", "je"]'::jsonb, null, 'Zabranjeno je hraniti životinje.', array['Hraniti životinje je zabranjeno.']::text[], null, null, null, '«Годувати тварин заборонено.» — «Zabranjeno je hraniti životinje.».', (select id from public.lessons where id = 'b9b0bb4b-ffcb-56e0-bbb0-a927fffa9f39'), 'PUBLISHED', 'claude_assessment_v5'),
  ('860492fa-27a5-5a96-8b5c-e3a06acb7093', v_aid, 44, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Він освідчився їй на пляжі.»', null, '["ju", "plaži.", "na", "Zaprosio", "je"]'::jsonb, null, 'Zaprosio ju je na plaži.', array['Na plaži ju je zaprosio.']::text[], null, null, null, '«Він освідчився їй на пляжі.» — «Zaprosio ju je na plaži.».', (select id from public.lessons where id = '68f2ada8-2352-5450-a073-72754ae0feb8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('466236ea-7086-5e32-80e3-59ec62f51faf', v_aid, 45, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Декларацію подають до кінця лютого.»', null, '["kraja", "veljače.", "predaje", "do", "se", "Prijava"]'::jsonb, null, 'Prijava se predaje do kraja veljače.', array['Do kraja veljače se predaje prijava.']::text[], null, null, null, '«Декларацію подають до кінця лютого.» — «Prijava se predaje do kraja veljače.».', (select id from public.lessons where id = '5f9af92b-06e1-5179-81a3-19625a5b8273'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e9a5fbab-ec0e-5dcc-a980-13dabf95b002', v_aid, 46, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я ніколи не забуду той день.»', null, '[]'::jsonb, null, 'Nikad neću zaboraviti taj dan.', '{}'::text[], null, null, null, '«Я ніколи не забуду той день.» — «Nikad neću zaboraviti taj dan.».', (select id from public.lessons where id = '92226a59-39e3-5dba-b0df-1e91b3dd2210'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7dab7c24-667b-5adf-ab5f-987ae28410af', v_aid, 47, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Ти пам’ятаєш свою першу вчительку?»', null, '[]'::jsonb, null, 'Sjećaš li se svoje prve učiteljice?', '{}'::text[], null, null, null, '«Ти пам’ятаєш свою першу вчительку?» — «Sjećaš li se svoje prve učiteljice?».', (select id from public.lessons where id = '92226a59-39e3-5dba-b0df-1e91b3dd2210'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bd286e8b-2821-5edd-a818-c798ea508a22', v_aid, 48, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Вуличне освітлення не працює.»', null, '[]'::jsonb, null, 'Javna rasvjeta ne radi.', '{}'::text[], null, null, null, '«Вуличне освітлення не працює.» — «Javna rasvjeta ne radi.».', (select id from public.lessons where id = '5ef67da9-21aa-58fa-91c2-d8144333a756'), 'PUBLISHED', 'claude_assessment_v5');
